WordHunterWoW_QuestEN[45329] = { title = "Operation: Portals", description = "This is a serious invasion, but nothing a Slayer like you can't handle. Time to put those weapons to work!", objectives = "Close 3 Legion portals.", completion = "That was surprisingly easy..." }
WordHunterWoW_QuestEN[45330] = { title = "Scouting Party", description = "We will have our work cut out for us finding the missing scouts and Lady S'theno. I suspect that one does not wish to be found.\n\nDo your best, {name}!", objectives = "Find Lady S'theno and 10 Illidari Scouts.", completion = "You got most of our scouts out alive. And Lady S'theno appears somewhat chastened, at least. Well done!" }
WordHunterWoW_QuestEN[45331] = { title = "Return to Acherus", description = "You've grown a lot since we last met, {name}. Now that we have the harness, let's see if Mograine has a plan to use it.", objectives = "Return to Highlord Darion Mograine in Acherus.", completion = "Welcome back, Deathlord. I see you were successful." }
WordHunterWoW_QuestEN[45332] = { title = "Tracking Quest - Zirux", description = "", objectives = "" }
WordHunterWoW_QuestEN[45333] = { title = "On Unhallowed Ground", description = "", objectives = "" }
WordHunterWoW_QuestEN[45337] = { title = "Mo'arg Brute Squad", description = "", objectives = "" }
WordHunterWoW_QuestEN[45339] = { title = "Defense of the Fel Hammer", description = "We need to get back to the Fel Hammer ASAP!", objectives = "Use the Illidari Gateway to return to the Fel Hammer.", completion = "That was quite a hit you took...\n\nFrankly, I'm amazed that the Fel Hammer didn't self destruct when we fired her weapons. We are lucky to be alive." }
WordHunterWoW_QuestEN[45340] = { title = "Sea Giant's Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[45341] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45342] = { title = "Administering Aid", description = "Unfortunately, it would seem many of your allies have already taken to fighting on these fel corrupted shores. \n\nThey will never be able to gain the upper hand in battle while so many are suffering from the contagion. \n\nTake the counteragent and use it to administer aid to your allies. \n\nRoland and I will handle the injuries here.", objectives = "Apply the Contagion Counteragent to sickly Legionfall Fighters.", completion = "Your allies have you to thank for their lives." }
WordHunterWoW_QuestEN[45343] = { title = "A Curious Contagion", description = "It has been brought to my attention that a rather curious contagion is spreading through a small coastal region within Highmountain.\n\nThe local tribes have abandoned the area for fear of catching this ailment that currently has no known cure.\n\nOne of our own was traveling through the area when her companion fell ill. She has requested the Conclave's assistance. Seek her out, High Priest, and do whatever you can to stop this sickness from spreading.", objectives = "Find Aelthalyste in Highmountain.", completion = "Ah, good. So the Conclave received my request. I didn't expect they'd send their leader!" }
WordHunterWoW_QuestEN[45344] = { title = "Sampling the Source", description = "My companion has fallen terribly ill, as you can see. \n\nHe must have caught whatever these taurens had. Their entire camp has been wiped out!\n\nIt appears to be fel in origin, and impervious to all known treatments. \n\nI've been working tirelessly to find a cure, but I don't think Roland here has much time left. \n\nI could use an extra hand. Some samples from the source should speed things up. \n\nJust be sure to avoid direct contact with the contagion. Levitate should be helpful.", objectives = "Collect Contaminated Specimens from pools of Gaseous Fel around the western coast of Highmountain.", progress = "Do you have the samples I've requested?", completion = "I hope you handled these samples with care, <name>. I wouldn't forgive myself if I was responsible for getting the High <class> sick." }
WordHunterWoW_QuestEN[45345] = { title = "Mischievous Sprites", description = "It's a little-known secret that the dust sprites use for their various tricks has restorative properties.\n\nSome within the alchemy community balk at this claim, but they only refute it because they've never been able to get their hands on the rare ingredient.\n\nSprites often shroud themselves in illusions to avoid detection.\n\nThe nearby goats have a curious shimmer about them that suggests they may be sprites in disguise.\n\nDispel whatever magic surrounds them to reveal their true form.", objectives = "Use Dispel Magic on Soothoof Hillstriders to reveal Mischievous Sprites and collect their Shimmering Dust.", progress = "Have you acquired the Shimmering Dust I so desperately need?", completion = "Thank you, <name>. I thought those goats seemed a little strange." }
WordHunterWoW_QuestEN[45346] = { title = "Shambling Specimens", description = "This fel contagion appears to have three stages.\n\nThe first is marked by a persistent, phlegmy cough.\n\nThe second shows the skin turning a sickly shade of green.\n\nThe third involves a complete transformation where the victim turns into a mindless corpse. It is within this stage that I believe the most information about the sickness can be gathered.\n\nI have a contraption that can safely store the specimens, but they will need to be shackled before they can be collected.", objectives = "Use Shackle Undead on Shambling Corpses in order to collect specimens with the Corpse Collector.", completion = "While there is no hope of curing those who have reached stage III, at least they will be able to provide crucial information about how the contagion works." }
WordHunterWoW_QuestEN[45347] = { title = "Crafting a Cure", description = "I used what you gathered for me to craft what I hope will be a reliable cure. The only thing that's missing is some powerful magic, which I hope you'll be able to provide.\n\nThe concoction is there on my alchemy table.\n\nPlease hurry, {name}. Roland grows weaker by the minute.", objectives = "Infuse the Untested Cure with magic before administering it to Roland Abernathy.", progress = "I will do whatever it takes to find a cure for this contagion.", completion = "Brilliant work, <name>. For a moment I thought I'd need to find a new companion." }
WordHunterWoW_QuestEN[45348] = { title = "Safekeeping", description = "It would seem that a delicate balance of holy and shadow magic is the key to curing this contagion. Obviously the remedy will need a bit of work to reduce undesired side effects, like dying.\n\nIn the meantime, take the counteragent back to Netherlight Temple and keep it safe. I will work diligently on discovering the source of this contagion.", objectives = "Take the Contagion Counteragent to Alonsus Faol in Netherlight Temple.", progress = "What do we have here?", completion = "This cure could not have come at a better time." }
WordHunterWoW_QuestEN[45349] = { title = "To the Broken Shore", description = "We've received word from those fighting on the Broken Shore. It seems the source of the contagion can be pinpointed to a specific island off the western coast.\n\nMany of our allies have already been infected. We must work quickly to ensure that the contagion doesn't spread.", objectives = "Head to the Broken Shore.", completion = "You're here, High <class>! Quickly, there's no time to lose!" }
WordHunterWoW_QuestEN[45350] = { title = "Countering the Contagion", description = "I have tracked the source of the contagion to these very shores. The Burning Legion are using fel spreaders to pump out infectious fel creep, causing anyone who comes into contact with it to become sick.\n\nTake out Ozzuk the Corrupter and his fel spreaders so that the contagion can be contained.", objectives = "Counter the contagion by killing Ozzuk the Corrupter and destroying his fel spreaders.", completion = "I believe our combined efforts have effectively eradicated the fel contagion from Azeroth.\n\nWell done, <name>." }
WordHunterWoW_QuestEN[45351] = { title = "Overloaded Soulshard", description = "", objectives = "" }
WordHunterWoW_QuestEN[45352] = { title = "Touch of a Titan", description = "Oh my! You've managed to acquire an item of legend to carry on your adventures. I've long theorized that such items draw their power directly from the titans, and this may prove to be a chance to test such speculation!\n\nIt is said that the Nightwell draws power from the Eye of Aman'Thul, and after centuries in close proximity I believe that titan's power now dwells within the inhabitants of the Nighthold. Bring me remnants of this energy, and I will empower your equipment.", objectives = "Bring 50 Essences of Aman'Thul to Arcanomancer Vridiel.", progress = "Aman'Thul has likely been slain for countless aeons, yet his power lingers. How is this possible?", completion = "Marvelous! It is such a joy to work with such magnificent craftsmanship. Please, come see me again should you find another such masterpiece." }
WordHunterWoW_QuestEN[45353] = { title = "Touch of a Titan", description = "Harnessing the strength of the titans may be the only thing that lets us push back the Burning Legion. Bring me more of this power, and we will improve your odds of defeating Gul'dan.", objectives = "Bring 50 Essences of Aman'Thul to Arcanomancer Vridiel.", progress = "Aman'Thul has likely been slain for countless aeons, yet his power lingers. How is this possible?", completion = "I count myself fortunate to be able to work with the heroes who fight for our world's survival." }
WordHunterWoW_QuestEN[45354] = { title = "Dispersion of the Discs", description = "These discs are radiating with power! It must be their proximity to one another. We must take them from here should they resonate further and cause a catastrophe in these sacred halls.\n\nI'll send them to the one place I know where we can reign their energies in, preventing any sort of explosion. I'm speaking of the Eye of Eternity.\n\nThere we will be able to safely finish what Antonidas was unable to complete. Speak with me again when you're ready to leave.", objectives = "Complete the trial to purge the excess energy from within the disc fragments.", completion = "To say you've earned your archmage status would be an understatement. Your success today proves that you were born one.\n\nNow mount your new vessel and ride against the Legion with all the might of your knowledge." }
WordHunterWoW_QuestEN[45358] = { title = "Contagion Containment", description = "", objectives = "" }
WordHunterWoW_QuestEN[45365] = { title = "Treasure: Wand of Simulated Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[45368] = { title = "Fel Shard", description = "", objectives = "" }
WordHunterWoW_QuestEN[45372] = { title = "Fate of the Nightborne", description = "Shortly after your victorious return from the Nighthold, urgent business took Thalyssra back to the palace.\n\nShe has requested that you meet her there.\n\nSpeak to me when you are prepared to join her.", objectives = "Speak to Oculeth and meet Thalyssra in the Nighthold.", progress = "Thank you for coming.", completion = "Thank you for being here, <name>.\n\nUltimately the Nightborne must shape their own destiny, regardless of the help we have received from Outlanders like yourself.\n\nIt is no easy burden we bear, but Elisande has shown us that we must stand alone, without the Nightwell, to properly rejoin the world.\n\nThank you for all you have done for us." }
WordHunterWoW_QuestEN[45379] = { title = "Treasure Master Iks'reeged", description = "<TEMP> Board the ship then kill fel bats.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 1 Felwing Devourers." }
WordHunterWoW_QuestEN[45381] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "Collect 4 Echoes of Time from Elisande in The Nighthold on Normal Difficulty.", progress = "Without the talisman we must fight through the city proper.", completion = "The power these fragments hold will allow me to call the talisman to us. Well done!" }
WordHunterWoW_QuestEN[45382] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "Collect 4 Echoes of Time from Elisande in The Nighthold on Heroic Difficulty.", progress = "Without the talisman we must fight through the city proper.", completion = "The power these fragments hold will allow me to call the talisman to us. Well done!" }
WordHunterWoW_QuestEN[45383] = { title = "The Nighthold: Talisman of the Shal'dorei", description = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", objectives = "Collect 4 Echoes of Time from Elisande in The Nighthold on Mythic Difficulty.", progress = "Without the talisman we must fight through the city proper.", completion = "The power these fragments hold will allow me to call the talisman to us. Well done!" }
WordHunterWoW_QuestEN[45385] = { title = "We Must be Prepared!", description = "The Legion ships are gone, for now. It's only a matter of time before they attack again, and we must be prepared.\n\nWe need to get going on repairs immediately! Lady S'theno took the lead on the search for parts. That one will do anything to remain on solid ground, ha! \n\nShe is waiting for you on the Broken Shore.", objectives = "Talk to Lady S'theno at the Illidari Camp on the Broken Shore.", completion = "About time, Sslayer <name>. We have work to do." }
WordHunterWoW_QuestEN[45386] = { title = "Imminent Launch", description = "Shadow {name}, what a relief!\n\nWe have alarms set up throughout Gnomeregan to detect any unauthorized personnel while we finish de-irradiating the city.\n\nJust about every single one was tripped in the past few hours.\n\nBased on your recon, it's a safe assumption that Thermaplugg is down there, and he has enough firepower with him to decimate anywhere he pleases!\n\nDon't worry, I can get you to Gnomeregan. Talk to the High Tinker once you're there and do whatever it takes.\n\nFor Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[45390] = { title = "Souls of the Vrykul", description = "", objectives = "" }
WordHunterWoW_QuestEN[45391] = { title = "Champion: Lady S'theno", description = "", objectives = "You have gone above and beyond to honor our pact, Sslayer <name>. You know I'm not one for sappy speechess, but I assure you that I am grateful.\n\nI will take my place by your side if you will have me." }
WordHunterWoW_QuestEN[45392] = { title = "Dark Memento", description = "The flowers were... a nice gesture.\n\n<Velonara sniffs one of the black roses.>\n\nI have a spare hood. Nothing fancy, but perhaps Moorgoth would like to have it.\n\nJust don't let him get his hopes up or anything. I'm merely repaying a kindness.\n\nI would appreciate it if you kept all this between us. Giving presents to admirers falls a bit outside the dark ranger rules of conduct.", objectives = "Bring Velonara's spare hood to Death Hunter Moorgoth.", completion = "Velonara asked you to deliver this to me personally?\n\n<Moorgoth's eyes sparkle as he grins from ear to ear.>\n\nShe DOES care! She DOES care!\n\n<Moorgoth settles down and clears his throat.>\n\nThat was kind of her. Say, it is a nice hood. I bet I could mass-produce this and offer it to my fellow dark ranger aficionados.\n\nWould you like to browse my wares?" }
WordHunterWoW_QuestEN[45393] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45394] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45395] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45396] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45397] = { title = "Fire the Cannons!", description = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me.  \n\n<Keeshan coughs up seawater, wiping his mouth dry with his sleeve.>\n\nUghh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", objectives = "Slay 14 demons." }
WordHunterWoW_QuestEN[45398] = { title = "Harnessing Power", description = "These fools are using the power of Rimefang's harness to subjugate the frost wyrms. Their leader, Andjor, sits inside on the back of the broodmother and mocks us.\n\nHe should breathe no longer.", objectives = "Kill Andjor Dragontamer and retrieve Rimefang's Harness.", progress = "This harness will bring us great power!", completion = "During my training, Mograine told me of what we could achieve with this harness. I look forward to the results." }
WordHunterWoW_QuestEN[45399] = { title = "Severing the Sveldrek", description = "So here's the order of things, as far as I've been told. Mortal walks into Icecrown. Mortal is brutally defeated. Mortal gets raised as Scourge.\n\nThese fools can't expect to trounce in here, do whatever they want, and leave without any consequence. Time to make them truly as mindless as they act.", objectives = "Kill and raise 8 Sveldrek vrykul.", completion = "Watching those vrykul shamble off mindlessly made my dead heart go \"pitter patter\"." }
WordHunterWoW_QuestEN[45404] = { title = "Panic at the Brewery", description = "We were not prepared for a surprise attack. I fear Brewmaster Blanche has been captured, or worse...\n\nPlease help me, Grandmaster!", objectives = "Help Almai find Brewmaster Blanche and defend Stormstout Brewery.", completion = "How could this have happened to us; to me? I never thought I would die so young... and so violently...\n\nWe have tried to Detox our fallen friends, but this poison is too advanced.\n\nI cannot rest while our order's very survival is still at stake. I am so sorry I let you down, Grandmaster <name>." }
WordHunterWoW_QuestEN[45405] = { title = "Breaching the Sanctum", description = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area.\n\nTake these telemancy orbs. If you find you need support, use them to summon Withered.\n\nWe must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", objectives = "Speak with Oculeth to start the assault." }
WordHunterWoW_QuestEN[45406] = { title = "The Storm's Fury", description = "No longer do we have time to prepare, the moment of action is upon us!\n\nCome with me, little one. With you guiding my aim we shall cleanse this isle by thunder and lightning!", objectives = "Destroy the Burning Legion forces within Shield's Rest.", completion = "Today will not be your end, hero. The Legion threatens the Gates of Valor and without the power you wield they will surely fall." }
WordHunterWoW_QuestEN[45412] = { title = "Protection: Aid of the Illidari", description = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city.\n\nKor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks.\n\nI do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more.\n\nSpecialization: Protection Warrior", objectives = "Find Kor'vas Bloodthorn in the streets of Dalaran.", completion = "You - I've seen you out on the isles.\n\nWe need to move quickly!" }
WordHunterWoW_QuestEN[45413] = { title = "Gathering Information", description = "The Legion has sent one demon after another to try to break into the Kirin Tor vaults in the city, but we don't know what they're after.\n\nLooks like they finally made it in.\n\nWe need to find out what was taken, and quickly, before they get a chance to put whatever it is to use.\n\nProbe any survivors for information - I'll use my spectral sight to make sure there aren't still any straggling demons lurking about.", objectives = "Question citizens in the Bank of Dalaran to find out what was stolen.", progress = "We can't risk another attack until we get to the bottom of this.", completion = "No... no, no, no, no!\n\nNot good. Not good at all." }
WordHunterWoW_QuestEN[45414] = { title = "Confirming Suspicions", description = "That heart is the last remaining piece of Highlord Kruul - once one of the Legion's best warlords.\n\nMany years ago Kruul's armies nearly descended upon the Dark Portal to crush the Azerothian assault on Outland. We Illidari intercepted before he could strike.\n\nI fear that the Legion aims to use the heart to hasten Kruul's resurrection in the nether. We must find the Prophet Velen at once - only he can tell us for sure.", objectives = "Find Prophet Velen in Dalaran.", progress = "This is deeply concerning.", completion = "Kruul must not be allowed entrance into this world." }
WordHunterWoW_QuestEN[45415] = { title = "Between Worlds", description = "Kruul boasts damnation, but his power has not yet fully manifested. His minions have taken his heart to hasten his rebirth in the nether.\n\nWe do not have much time.\n\nGo to the place of Kruul's fall at the Stair of Destiny in desolate Outland, where the link to his soul is strongest. There you must pry open the way to his realm.\n\nI must prepare for the battle to come. Good luck, champion.", objectives = "Establish a portal to the Twisting Nether at the Stair of Destiny in Outland.", progress = "Lord Illidan led us into glorious battle against Kruul long ago. Now you must do the same.", completion = "We must strike before Kruul reaches his full strength, but we're going to need help." }
WordHunterWoW_QuestEN[45416] = { title = "The Highlord's Return", description = "I have a missive for you from Kor'vas, as well as instructions for getting you there.\n\nI can teleport you to them to begin the fight, but you will need some Nethershards to force your way into the Twisting Nether.\n\nWhen you have enough, speak with me and you can begin.", objectives = "Defeat Highlord Kruul in the Twisting Nether. Speak with War Councilor Victoria to get there.", completion = "Kruul will never again threaten our world, or any other.\n\nProphet Velen sends his thanks, Archdruid." }
WordHunterWoW_QuestEN[45417] = { title = "The Nighthold: Lord of the Shadow Council", description = "As we speak, Gul'dan is using the Nightwell's power to pull Sargeras into our world.\n\nGather your companions and fight your way to the top of The Nighthold.\n\nI will prepare Light's Heart and join you when the time is right.\n\nTogether, we will put an end to Gul'dan once and for all.", objectives = "Defeat Gul'dan in The Nighthold.", completion = "A fitting end." }
WordHunterWoW_QuestEN[45420] = { title = "The Nighthold: The Eye of Aman'Thul", description = "The battle is won, but the war is far from over.\n\nIn order to stem the tide of demons flooding into Azeroth, we must use the Pillars of Creation to seal the Tomb of Sargeras.\n\n<Khadgar peers down at the Eye of Aman'Thul.>\n\nThat... might be difficult to carry.\n\nPerhaps I can use the power of the Eye itself to teleport it to Dalaran. I suppose there is only one way to find out!", objectives = "Aid Khadgar in transporting the Eye of Aman'Thul.", completion = "With the Eye of Aman'Thul in our possession, we are one step closer to sealing the portal." }
WordHunterWoW_QuestEN[45421] = { title = "Vignette: Dirge of Asgrim", description = "", objectives = "" }
WordHunterWoW_QuestEN[45422] = { title = "Edict of the God-King", description = "Our scouts send troubling reports from Stormheim.\n\nGod-King Skovald has received a new directive from Gul'dan. In response, Skovald's forces have stepped up their attacks.\n\nWe must know the details of Gul'dan's message, <name>.\n\nDespite his new orders, the god-king remains obsessed with the titan keeper Odyn. Intercept Skovald in the Halls of Valor and you may determine what his Legion masters have demanded of him.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat God-King Skovald in Halls of Valor on Mythic difficulty." }
WordHunterWoW_QuestEN[45423] = { title = "Wailing Critters", description = "I'm glad you're here, {name}.\n\nTiny wails have been heard in the caverns for some time since Naralex was awakened. At first, we suspected that some deviate critters had survived. Upon further investigation, we found them to be growing and multiplying beyond our wildest expectations. The corpse of Verdan the Everliving may have something to do with it, we're not sure. That's why we're sending you in.\n\nI've also seen suspicious footprints leading into the caverns recently. We may not be alone, be careful.", objectives = "Defeat the Budding Everliving Spore in Wailing Caverns.", progress = "Have you completed your investigation the Wailing Caverns?", completion = "Yes, I saw the shadowy character as well, he ran right past me. Probably a tauren, but we can't be sure. Keep a look out for him, something tells me we're just beginning to unravel this mystery." }
WordHunterWoW_QuestEN[45425] = { title = "Grovebound", description = "Now THAT was some good stuff right there. Now that we've taken out the commander, the druids and the ancients should be safe for a while. Revenge was an added bonus.\n\nWe should get back to Rensar and tell him what we accomplished.", objectives = "Return to Rensar Greathoof in the Dreamgrove.", completion = "We have asked a lot of you over the last few months, <name>. You not only rose to our expectations, but surpassed them. By killing Katith'rax, you have stopped the attacks against our ancients.\n\nYou deserve the position of Archdruid of the Dreamgrove. I am honored to be your colleague, and expect us to do much for the world. Together." }
WordHunterWoW_QuestEN[45426] = { title = "Nature's Advance", description = "{name}, you must return to the Dreamgrove and bring the news of my attack. Tell the other druids that aggressions such as this will continue against us unless we find a way to stop the Legion.\n\nI thank you for the aid. I feel the fel energies leaving my veins, though it may take some time.", objectives = "Return to Rensar Greathoof in the Dreamgrove.", completion = "What news do you have of the attack on Aviana's shrine?" }
