WordHunterWoW_QuestEN[45437] = { title = "An Urgent Situation", description = "Archmage, {name}! We have an important guest. Please meet me in my chamber when you have a moment.", objectives = "Find Meryl's visitor in the Hall of the Guardian.", completion = "I have been unfairly maligned by many. I am glad the Tirisgarde does not fall prey to petty rumors!" }
WordHunterWoW_QuestEN[45438] = { title = "Armies of Legionfall [DEPRECATED]", description = "The Legion has increased their assaults across our lands. We must be the spearhead and convince the forces of Azeroth to come together! \n\nUnder your leadership, old grievances must be put aside for the sake of our very survival. It is a daunting task, but I know of one who is worthy to take it on.\n\nThe orc warrior, Eitrigg, is well respected by all Horde. Ask him to spread our message!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Go to Orgrimmar and ask Eitrigg to rally the orders of Azeroth." }
WordHunterWoW_QuestEN[45439] = { title = "An Invasion of... Murlocs?", description = "", objectives = "" }
WordHunterWoW_QuestEN[45440] = { title = "A Brewing Situation", description = "Greetings, Grandmaster. I'm an expert at producing tricky brews, and Almai and I have been working with Stormstout Brewery to craft Storm Brew for the order. \n\nIn fact, we have already begun production!\n\nThat calls for a party, don't you think? We brought enough of my prized Celebration Brew for everyone!", objectives = "Direct the Stormstout Brewers to distribute Celebration Brew to the temple balcony, in front of the Laughing Crane, and near the troop training grounds.", progress = "Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*", completion = "Whew. Celebration brew is..*hic* shtronger than I remembered it to be. *urp*" }
WordHunterWoW_QuestEN[45441] = { title = "Adacic Grubs - REWORK", description = "Your request to harvest wood does not seem unreasonable, {name}. There is something you can do for me, too.\n\nThere is a species of moth whose grubs feed on trees. Normally their numbers are too low to cause damage, but once a century they reproduce in overwhelming numbers. \n\nThey have just begun their mass emergence. All of my keepers are fighting the nightmare and cannot be spared. I fear I am unable to protect the forest giants on my own.\n\nWill you stomp the grubs out?", objectives = "Stomp out 50 Adacic Grubs" }
WordHunterWoW_QuestEN[45442] = { title = "Not Felling Well", description = "Let's see... Yseralline Seed for healing, Bruiseweed for curing poison, and Elemental Earth for disease resistance. Oh and just a touch of ground Felwort for attunement. \n\nYes, I think this will counteract the Legion's poison. It will probably taste terrible, but what medicine doesn't?\n\nHurry, Grandmaster {name}. Our most stricken friends don't have much time left.", objectives = "Use Blanche's Still and then give the Curative Brew to 8 Fel-Poisoned Initiates.", progress = "Did our Curative Brew work?", completion = "It makes my heart glad to see our order returning to health." }
WordHunterWoW_QuestEN[45447] = { title = "Turned In Marin's Coin", description = "", objectives = "" }
WordHunterWoW_QuestEN[45449] = { title = "Alchemist Korlya", description = "The zealots within the Garrison of the Fel are led by Alchemist Korlya. It seems likely that's the Felskorn Brewmaster Blanche observed poisoning our brew.\n\nPlease kill her.", objectives = "Kill Alchemist Korlya.", completion = "Thank you. That's one less demon working against us." }
WordHunterWoW_QuestEN[45459] = { title = "Storming the Legion", description = "I did my best to fight the demons off, but there were too many even for my skill...\n\nAs I lay dying, I overheard the dreadlord commanding a Felskorn alchemist to contaminate my brew and then return to the Broken Shore. \n\nIf you could acquire some of the poison, I'm sure we can concoct an antidote!", objectives = "Talk to Tak-tak to travel to the Broken Shore.", completion = "Good, you made it!" }
