WordHunterWoW_QuestEN[45482] = { title = "Arcane: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.\n\nSpecialization: Arcane Mage", objectives = "Search Jandvik for the vrykul mentioned in the scrolls.", completion = "Yes, outsider? What business do you have here?" }
WordHunterWoW_QuestEN[45483] = { title = "Ealdis", description = "", objectives = "" }
WordHunterWoW_QuestEN[45484] = { title = "Harbinger of Screams", description = "", objectives = "" }
WordHunterWoW_QuestEN[45485] = { title = "Aodh Witherpetal", description = "", objectives = "" }
WordHunterWoW_QuestEN[45486] = { title = "The Reluctant Queen", description = "Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline.\n\nI don't know who you are, nor do I believe I'm part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you.\n\nMeet me in Valdisdall, {class}. From there we can make our way to Skold-Ashil and request an audience with Eyir. Perhaps she can shed some light on this prophecy.", objectives = "Bring Sigryn before Eyir in Skold-Ashil.", completion = "I thank you for bringing Sigryn to me, outsider. She truly is the future of our people.\n\nThough you have already done so much, I would ask another favor of you. Please accompany Sigryn in her challenges. She has grown to trust you, and will need guidance through the trials she must face." }
