WordHunterWoW_QuestEN[45498] = { title = "Let Sleeping Dogs Lie", description = "You see those big eredar guys? That's the barrow that Goldrinn is in! I don't know what the Legion is doing to him in there, but I'm sure we don't want them to succeed.\n\nLet's get in there and save Goldrinn!", objectives = "Save Goldrinn from the Stormrage Barrow Dens.", progress = "Who knows what the Legion could be doing to Goldrinn!", completion = "We did it! We saved Goldrinn!" }
