WordHunterWoW_QuestEN[45522] = { title = "To Silence the Bonespeakers", description = "Sigryn's claim to the throne will be challenged by two rivals - Runeseer Faljar of the Bonespeakers and Jarl Velbrand of the Drekirjar.\n\nI would begin in Haustvald with the Runeseer. He was a close ally of Skovald and is a powerful mystic. With the Bonespeakers at his charge, he would prove a staunch opponent if he cannot be made to yield.\n\nGo now, and claim your destiny in the name of the Valkyra!", objectives = "Defeat Runeseer Faljar in Haustvald.", completion = "The Bonespeakers yield. Our clan will not interfere with Sigryn's claim to the throne.\n\nBe careful of this one, <class>. I can see the darkness that consumed Skovald dwelling in this girl's heart. How she has resisted it this far, I do not know.\n\nYou had best hope she can control it." }
WordHunterWoW_QuestEN[45523] = { title = "To Tame the Drekirjar", description = "The Bonespeaker's words trouble me, outsider. The darkness he speaks of, Skovald's fel curse, could he have passed it onto me somehow?\n\nNo, it cannot be so. The Runeseer must be mistaken...\n\nCome, the next challenger awaits. I will no doubt need your assistance bringing him to heel as well.", objectives = "Defeat Jarl Velbrand in Hrydshal.", completion = "You have the backing of the Dragon-Riders, but a greater rival to the throne still lives in secret.\n\nThe God-King's son yet lives. My riders spotted him among the outcasts of Vrekt. He would be the true heir to Skovald's throne.  \n\nThe vrykul would never follow you were he to contend your claim!" }
WordHunterWoW_QuestEN[45524] = { title = "The Forgotten Heir", description = "My brother... lives?\n\nThe last time I saw him, the assassins were closing in on him. I can't imagine how he defeated them...\n\nWe should travel to Vrekt. I would look upon my brother with my own eyes.", objectives = "Find Torvald in Vrekt.", progress = "Let us go to Vrekt.", completion = "I cannot believe that I find my brother alive, only to see him fall by my own blade. \n\nHow can fate be so cruel?" }
WordHunterWoW_QuestEN[45525] = { title = "Unanswered Questions", description = "What is done, is done. There are none left to challenge the throne of the Tideskorn. \n\nMy brother's words still haunt me, though. If Eyir knows who ordered my family killed, I deserve to know it.\n\nCome, let us return.", objectives = "Join Sigryn at the Vault of Eyir in Skold-Ashil.", completion = "Sigryn has taken the path of Skovald before her. Only, I fear she is more powerful than her father ever was. \n\nI fear that Sigryn's thirst for revenge may lead to her undoing. Though truly powerful, she would be no match for Odyn.\n\nShe must be stopped before it is too late." }
WordHunterWoW_QuestEN[45526] = { title = "The God-Queen's Fury", description = "{class}t, the Kirin Tor have found a way to get you into the Halls of Valor to pursue the God-King's heir. Archmage Khadgar has asked me to stress upon you the importance of stopping Sigryn, as the prophecies hint that she may still be the key to uniting the Tideskorn against the Legion.\n\nIt will require an incredible amount of energy to teleport you directly to the Halls, so be sure that you are prepared. It may be some time before we can send you again.\n\nSpeak to me when you are ready to proceed.", objectives = "Speak with War Councilor Victoria to be teleported to Sigryn's location and defeat her.", completion = "I... thank you for coming for me. I hope you can forgive me for what I've done.\n\n\nI will return to Eyir. I only hope she can grant me her forgiveness as well..." }
WordHunterWoW_QuestEN[45527] = { title = "Eyir's Forgiveness", description = "I'm sorry for everything I've put you through, outsider. After my actions here, I fear all of this may have been in vain.\n\nCome with me back to Skold-Ashil. There I will accept whatever judgment Eyir  deems fit of me.", objectives = "Witness Eyir's judgment of Sigryn in the Vault of Eyir in Skold-Ashil.", completion = "To think, when you met me I had all intentions of living out my days as a farmer. Little did I know that the gods had other plans for me.\n\nThank you, outsider, for showing me my true purpose. I only hope I can live up to Eyir's visions and truly unite the Tideskorn once more.\n\nIf that day comes, the Legion will regret ever setting foot in Stormheim." }
WordHunterWoW_QuestEN[45528] = { title = "The Befouled Barrows", description = "You were taking too long, so I took the liberty to scout out the barrows in advance. The Legion has set up portals, pulling more and more demons through them by the second. We need to shut them down so we can save Goldrinn!\n\nI'm not sure my usual methods are going to do much to take them down, but I think you can do it! I think some nice vine-work is in order.", objectives = "Close 3 Legion Portals in the Stormrage Barrow Dens.", progress = "If we call up some vines to close the portals, then the Legion can't come through.", completion = "Now the demons can't call reinforcements. That was great!" }
WordHunterWoW_QuestEN[45531] = { title = "Creeping Fel", description = "", objectives = "" }
WordHunterWoW_QuestEN[45532] = { title = "Mother's Orders", description = "That big ugly thing looks like it's leading the attack here. Let's take her down!", objectives = "Kill Mother Mirenda.", completion = "What did she say about a distraction?! This isn't sounding good..." }
WordHunterWoW_QuestEN[45533] = { title = "Legion Dungeon Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[45534] = { title = "A Common Enemy", description = "I have one more request to ask of you, outsider.\n\nReturn to your leaders and report to them what transpired here.  Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. \n\nWhen the time comes, I hope to see you on the battlefield.", objectives = "Return to Khadgar in the Violet Citadel.", completion = "Remarkable! So there really was something to that prophecy after all!\n\nI am glad that Sigryn will lead the vrykul instead of the brutes who challenged her. Let us just hope she can unite the Tideskorn under her banner before the Legion has this place overrun.\n\nWell done, <name>!" }
WordHunterWoW_QuestEN[45536] = { title = "2v2 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45537] = { title = "3v3 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45538] = { title = "10v10 Weekly Quest UI", description = "", objectives = "" }
WordHunterWoW_QuestEN[45539] = { title = "Pet Battle Challenge: Wailing Caverns", description = "The deviate critters of the Wailing Caverns continue to flourish in the damp darkness, but I've been doing my best to keep their numbers down.\n\nI've found a few pets and supplies while clearing out the caverns, I might be willing to part with a sack of supplies if you can beat my best run.\n\nYou'll have to clear out the cavern without healing or reviving any of your pets to best me. Good luck!", objectives = "Defeat the Budding Everliving Spore in Wailing Caverns.", progress = "How is the battle for Wailing Caverns going?", completion = "Wow, that's impressive! Here's the sack of supplies, you earned it! Sorry about the dampness." }
WordHunterWoW_QuestEN[45540] = { title = "A Call from the Caverns", description = "Oh, good, I'm glad you stopped by. We've heard disturbing rumors of corruption continuing to flourish in the Wailing Caverns. You seem like just the right person to investigate.\n\nSince Naralex's awakening, one of his disciples has been watching over the area to ensure that deviate creatures remain in check. She is the one that has been sending us these dire warnings.\n\nMeet up with her in the eye of the skull-shaped rock above Wailing Caverns and see if you can help her handle this situation.", objectives = "Find Muyani in the skull-shaped rock above Wailing Caverns.", completion = "Thank you for coming, I have some interesting news about what's been going on in the Wailing Caverns since Naralex has awakened." }
WordHunterWoW_QuestEN[45541] = { title = "How Do YOU Like It?!", description = "", objectives = "" }
WordHunterWoW_QuestEN[45542] = { title = "Behind Enemy Portals", description = "", objectives = "" }
WordHunterWoW_QuestEN[45545] = { title = "Barrel Toss", description = "The Legion is defending the Felskorn lair with fel emitters. Fortunately we have Storm Brew to spare, so there should be plenty available with which to destroy them. \n\nTake this barrel, throw it at the spreaders, and watch them go BOOM!", objectives = "Use Storm Brew to destroy 5 Fel Brew Spreaders.", completion = "Blowing up demons never gets old, does it? Ha!" }
WordHunterWoW_QuestEN[45546] = { title = "Free Attempt Used", description = "", objectives = "" }
WordHunterWoW_QuestEN[45549] = { title = "Salving the Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[45550] = { title = "Salving the Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[45551] = { title = "Devastating Effects", description = "The Burning Legion will not rest until they have destroyed everything and everyone. Their presence here has had a devastating effect on our lands, and now it seems our wildlife as well. \n\nI have heard numerous reports of sickly animals in the thicket that surrounds the demon-infested city of Suramar. \n\nMake your way there and see if the rumors are true.", objectives = "Investigate Suramar.", completion = "<Nighthuntress Syrenne's pet is too weak to react to your presence.>" }
WordHunterWoW_QuestEN[45552] = { title = "Soothing Wounds", description = "<D'Bynn's injuries prevent him from moving.>\n\nPerhaps you can forage something nearby that will soothe the manasaber's wounds?", objectives = "Use Manaroot that is foraged from leylines within the Crimson Thicket to soothe D'Bynn's wounds.", completion = "<D'Bynn gently nuzzles your hand.>" }
WordHunterWoW_QuestEN[45553] = { title = "The Nighthuntress Beckons", description = "<D'Bynn becomes alert at the sound of his master's voice. Using his muzzle, he nudges your hand with a sense of urgency, inviting you to hop on his back.>", objectives = "Ride D'Bynn and let him lead you to Nighthuntress Syrene's location.", completion = "I suppose I have you to thank for saving my beloved companion." }
WordHunterWoW_QuestEN[45554] = { title = "Taking Control", description = "I've been withering away in this cage, prisoner to a wretch called Reyln.\n\nHe leads a group of nightborne that are using fel magic to corrupt and control the native wildlife.\n\nThe Burning Legion's reach has already spread too far for my liking.\n\nKill him and recover his control orb, so I can be released from this arcane prison!", objectives = "Kill Torturer Relyn and use his Control Orb to free Nighthuntress Syrene.", progress = "Relyn's control orb is the only thing that can break this magical barrier.", completion = "I have encountered many outsiders in my time patrolling the city, but never one quite as resourceful as you." }
WordHunterWoW_QuestEN[45555] = { title = "Felbound Beasts", description = "So Reyln is taking orders from Lexera? Why am I not surprised. She seemed far too comfortable with the demons who infested our city.\n\nWe cannot let her succeed in corrupting Suramar's wildlife. I swore to protect the city of Suramar from all enemies, even those within its walls.\n\nIf you can deal with her trappers, I will do my best to track Nighthuntress Lexera down.", objectives = "Kill Nightborne Trappers and free Felbound beasts.", completion = "You continue to surprise me, outsider." }
WordHunterWoW_QuestEN[45556] = { title = "Ready to Strike", description = "I followed one of the trappers, who unknowingly led me to the Broken Shore. \n\nLexera was there, surrounded by an army of demons and loyal nightborne.\n\nI wasn't able to get close, but from what I could tell, she and her army of trappers are taming the fel-corrupted beasts.\n\nIt is an abomination of nature, and she must be stopped!\n\nMeet me on the Broken Shore and be ready to strike. I will gather additional manaroot. I have a feeling we'll need it.", objectives = "Meet Nighthuntress Syrenne on the Broken Shore.", completion = "Let's make this quick. It won't be long before more demons come rushing through this pass." }
WordHunterWoW_QuestEN[45557] = { title = "Unnatural Consequences", description = "Lexera and her trappers have taken over the valley.\n\nShe is stronger than she looks, {name}, and she fights with the strength of a dreadlord. Do not go in unprepared. \n\nI can handle these demons. Go, find Lexera, and make her feel the consequences of her unnatural endeavors.", objectives = "Kill Nighthuntress Lexera.", progress = "Lexera and her trappers must be stopped.", completion = "There is no joy when a Nighthuntress falls, but it had to be done. The truth is, she died the moment she aligned herself with the Burning Legion." }
WordHunterWoW_QuestEN[45559] = { title = "Behind Enemy Portals", description = "", objectives = "" }
WordHunterWoW_QuestEN[45560] = { title = "Destruction: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.\n\nSpecialization: Destruction Warlock", objectives = "Find Navarrogg at the Misty Coast in Highmountain.", completion = "Thank you for coming. I am glad you are treating this threat seriously." }
WordHunterWoW_QuestEN[45561] = { title = "Seek Me Out", description = "The letter from Maximillian is written on something which looks to be torn off a ship's sail. Included are directions to the beach in northern Highmountain.", objectives = "Look for Maximillian of Northshire in Highmountain.", progress = "Look for Maximillian of Northshire in Highmountain.", completion = "Are you ready to begin?" }
WordHunterWoW_QuestEN[45562] = { title = "Kneel and Be Squired!", description = "You must kneel before me if we are to begin our journey together once more. Kneel, squire, and be squired!", objectives = "Kneel before Maximillian.", completion = "Very good, now we can begin!" }
WordHunterWoW_QuestEN[45563] = { title = "The Shrouded Coin", description = "A swirling mist envelops the coin and it begins to float above your hand. The mist briefly parts to reveal a shiny new coin, yet in the next instant the coin appears worn from years of exchange. As the coin settles back in to your hand, visions of jungles and mist shrouded peaks waft into your mind, and through the vision you recognize the four Celestials gathered in the courtyard of an island.", objectives = "Bring the Shrouded Timewarped Coin to Mistweaver Xia on the Timeless Isle.", completion = "Coins are interesting items. They travel far and wide across the lands, yet this one seems to also travel through time.\n\nThe fact that you found this coin where you did is both an omen and a blessing." }
WordHunterWoW_QuestEN[45564] = { title = "The Burning Birds", description = "The Feltotem are experimenting on these falcosaurs! They didn't get the results that they wanted and have carelessly left their experiments lying around to further poison the animals.\n\nWe should collect their leftover totems to prevent further corruption and to find out what they were doing.", objectives = "Collect Fel Infusing totems.", progress = "These animals are unable to be infused with fel magic, but I doubt the Feltotem stopped here.", completion = "There were quite a few guards as I scouted around. I noticed more strange things on the other side.\n\nLet me see those totems." }
WordHunterWoW_QuestEN[45565] = { title = "Further Training", description = "The journey here was perilous, Squire. It was fraught with danger. Storms, demons, storm demons... I shudder at the memory. Of course, I overcame all such dangers at great loss to my person. This is where I need your assistance.\n\nYou must venture forth--nay, sally forth--and recover my armor, my weapon, and of course my grand steed. Once you have successfully completed these tasks three, will you be promoted to Squire, First Class!", objectives = "Complete Maximillian's quests and slay \"demons\" to earn the rank of Squire First Class.", completion = "Very good, Squire- First Class!  Now the real journey begins!" }
WordHunterWoW_QuestEN[45566] = { title = "A Knight's Belongings", description = "Amidst the squalls and the crashing waves, my mighty ship swayed and tumbled. Lesser knights would have trembled in terror, frozen stiff. Not me! Nay! Heroically, I stripped my armor off my back and stored it safely in my sack. \n\nWhy did I strip down to these simple undergarments, you ask? Only an ignorant squire would. I was wary of sinking to the bottom should my ship fall foul of course! Ha ha! \n\nUnfortunately, the sacks of armor were thrown overboard by the waves.", objectives = "Fetch Maximillian's armor.", progress = "Fetch Maximillians armor.", completion = "Excellent, you found my armor." }
WordHunterWoW_QuestEN[45567] = { title = "My Kingdom for a Horse", description = "Oh, woe is me! Soon after making landfall I began exploring, riding my trusty steed Pimento into the heart of a demon infested village to the north. While performing my investigations, I tied Pimento up to go further on foot, only to return and discover a powerful demon had captured her! There he was, riding her like she was his own. Please find her and send her back to me.", objectives = "Return Pimento.", completion = "Pimento!  You found him!" }
WordHunterWoW_QuestEN[45568] = { title = "They Stole Excaliberto!", description = "I was scouting the nearby demon village when I was attacked. They took my artifact! Of course, if I leave here, the shore will be undefended. The nearby demons have it. Go, slay them and bring it back to me!", objectives = "Find Excaliberto and return it to Maximillian.", progress = "Find Maximillians \"Artifact\" weapon, Excaliberto", completion = "Yes!" }
WordHunterWoW_QuestEN[45570] = { title = "In Safer Hands", description = "There is still the matter of the Focusing Iris. Please return it to  your Kirin Tor friends, with my apologies.\n\nAs for myself, I think I'm done chasing artifacts for a while. One possession by immortal shadowy evil is enough for me, thank you.", objectives = "Bring the Focusing Iris to Archmage Kalec in Dalaran.\n\nProvided item:", completion = "At last, the Focusing Iris is returned! I will rest easier knowing it is once again safe in the vaults.\n\nI'm sorry to hear about Xylem, though I'm happy he survived the ordeal. He may be eccentric, but his heart is in the right place. \n\nWe can use more allies like him in the wars to come." }
WordHunterWoW_QuestEN[45571] = { title = "A Bit of Espionage", description = "With the gunpowder in tow, it's time to move on to our next plan. Meet us on the Broken Shore. \n\nYou can get a flight directly to our next location from Krasus' Landing. We will meet you there, {class}t.", objectives = "Speak to Aludane Whitecloud in Krasus' Landing for a flight to Broken Shore.", completion = "Good, you're here. Let's get to work." }
WordHunterWoW_QuestEN[45572] = { title = "Holding Our Ground", description = "Though we anticipated a strong Legion presence, our attacks on their camps have angered their forces even further than anticipated. Our forces rally on both land and in the skies above Thunder Totem in an attempt to regain our footing.\n\nDo what you can to reduce their forces. Once we've secured Thunder Totem we'll begin our plan for a final attack.", objectives = "Repel the Legion threat from Thunder Totem.", completion = "We must remember our allies who have fallen on this day and in their honor, continue our fight.\n\nThe time is upon us, <name>. Our riders are ready. Let us show the Burning Legion the true strength of Highmountain." }
WordHunterWoW_QuestEN[45573] = { title = "Rise Up", description = "Here we are, {class}t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it.\n\nThere's no time to explain the plan in full right now, but Tess has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", objectives = "Kill 8 demons, then reach the top of the ramp.", completion = "Easy as pie, Shadowblade. Now is when the plan kicks into action!" }
WordHunterWoW_QuestEN[45574] = { title = "Fel Ingredients", description = "Our scouts have located a Felskorn encampment within the Garrison of the Fel. We will need as many samples of fel poison as we can find if we are to concoct a cure for our stricken monks.\n\nTake samples of anything that looks remotely useful!", objectives = "Acquire 5 Vials of Liquid Felflame, 3 Flasks of Fel Blood, and 3 pinches of Demonic Ash.", progress = "Did you find any samples we can use?", completion = "Let's hope that's enough to brew a cure for our dying monks!" }
WordHunterWoW_QuestEN[45575] = { title = "Village of the Corruptors", description = "The Feltotem continue to create these totems for further \"experiments\". Let us deal with these infusers in the traditional manner.\n\nTheir deaths will right a great wrong and provide clues as to their ultimate goal.", objectives = "Kill Feltotem Infusers in Feltotem.", progress = "These Feltotem need to be dealt with.", completion = "Tugar... I thought he was dead. He was a nasty Bloodtotem even before the Legion arrived.\n\nWe have to get to him." }
WordHunterWoW_QuestEN[45576] = { title = "Rise Up", description = "Here we are, {class}t. On this island is a cavern full of exceptionally powerful demons and their leaders. If our plan succeeds, these demons will be... \"blown to smithereens\", as Tethys so nicely put it.\n\nThere's no time to explain the plan in full right now, but Lilian has agreed to walk you through it. First you must get up to the top of this ramp. Slaughter a few on your way.", objectives = "Kill 8 demons, then reach the top of the ramp.", completion = "Ah, my blade sings. Time to put this plan into action, Shadowblade." }
WordHunterWoW_QuestEN[45577] = { title = "thing", description = "", objectives = "" }
