WordHunterWoW_QuestEN[45586] = { title = "Shield Amplification", description = "It will not hurt to reinforce the Nightborne Soulstone's shield just a bit more, and to do that we must infuse it with energy. \n\nRyanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin'dorei well know, desperate times call for desperate measures.\n\nIt is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. \n\nDo what must be done.", objectives = "Use the Nightborne Soulstone on defeated Felborne within the Weeping Terrace.", completion = "Good. The Soulstone's shields should be sufficiently strengthened now." }
WordHunterWoW_QuestEN[45587] = { title = "The Feltotem Menace", description = "If I had known Tugar was alive and behind this I would've alerted you sooner! He is a hateful creature, and an easy recruit to the Legion's cause.\n\nIf he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let's go!", objectives = "Find and deal with Tugar Bloodtotem.", completion = "That was powerful fel magic. If it is true, if he is raising an army of such beasts... Thunder Totem is in peril!" }
