WordHunterWoW_QuestEN[45614] = { title = "Lady Remor'za", description = "Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. \n\nTheir leader, Lady Remor'za, and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. \n\nHowever, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!", objectives = "Kill Lady Remor'za.", completion = "The Felborne will respect the Tirisgarde now, do you not agree?" }
WordHunterWoW_QuestEN[45615] = { title = "Finders Keepers", description = "Would you look at this place? It's a mess! Everywhere you look there's just pile after pile of arcane dust!\n\n<Akazamzarak smiles broadly.>\n\nThese poor saps don't realize what that stuff's worth!\n\nI tell ya what, if you help me summon up some brooms to collect this powdered gold, I'll split the profits with you 80/20.", objectives = "Sweep up 8 piles of Arcane Dust in the Hall of the Guardian.", progress = "Say, how's that dust coming along?", completion = "Now that's what I'm talking about! You know what they say - where there's mages, there's dust!" }
WordHunterWoW_QuestEN[45616] = { title = "Grievous Gladiator's Dreadplate Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[45617] = { title = "Grievous Gladiator's Dragonhide Armor", description = "", objectives = "" }
