WordHunterWoW_QuestEN[45626] = { title = "Set You Up the Bomb!", description = "", objectives = "" }
WordHunterWoW_QuestEN[45627] = { title = "Feltotem's Fall", description = "Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced.\n\nHe's sent a message crystal along with some instructions for me.\n\nI can teleport you to Navarrogg and he will take you to Tugar's location, but there is one problem.\n\nNavarrogg requires additional magical power to fend off Tugar's fel magicks. You will need some Nethershards before you go.", objectives = "Defeat Tugar Bloodtotem. Speak with War Councilor Victoria, she will teleport you to Navarrogg to begin.", completion = "Thunder Totem and countless lives are saved. One more crisis down in this war against the Legion." }
WordHunterWoW_QuestEN[45628] = { title = "This Time, Leave a Trail", description = "Are you ready, {class}t? I will walk you through every step of the plan. You'll be perfectly safe! First thing's first: You see that rappel point behind me? That's your way down into the cave. Good luck!", objectives = "Rappel down into the cave, then follow Tess's instructions.", completion = "That couldn't have gone better if I had done it myself. Good work, Shadowblade." }
WordHunterWoW_QuestEN[45629] = { title = "This Time, Leave a Trail", description = "Here goes nothing, {class}t. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave.\n\nWhat? Don't make that face. I'll give you more instructions once you're in the cave.", objectives = "Rappel down into the cave, then follow Lilian's instructions.", completion = "That couldn't have gone better if I had done it myself. Good work, Shadowblade." }
WordHunterWoW_QuestEN[45630] = { title = "Servant to No One", description = "I like workin' with ya, {name}. How's about we keep this gold train a-rollin'?\n\nArchmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative?\n\n<Akazamzarak hands you a small crystal.>\n\nThis bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up.\n\nWhy not take it into town and try her out? See for yourself!", objectives = "Test Akazamzarak's Servants on 5 people in Dalaran.", progress = "Good stuff, am I right?", completion = "You make a pretty good business partner, bud! I'll see what I can do to get ol' Khadgar on board with these new servants. \n\nI tell ya I'm gonna make a fortune!\n\nOh, don't think I forgot you. I've got somethin' special in mind for ya!" }
WordHunterWoW_QuestEN[45631] = { title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost." }
WordHunterWoW_QuestEN[45632] = { title = "Missing in Action: Eitrigg", description = "Are you familiar with Eitrigg? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby.\n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", objectives = "Find Eitrigg.", completion = "The filthy naga ambushed me. I will not fail again." }
WordHunterWoW_QuestEN[45633] = { title = "Operation Felrage", description = "I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", objectives = "Kill Warlord Kaz'jatar and Felbeard.", progress = "Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", completion = "With their leaders defeated, the Felrage naga will not be preying on our warriors again. Still, we should keep an eye on them in the future." }
WordHunterWoW_QuestEN[45634] = { title = "Kvaldir on Call", description = "You empowered Helya's Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. \n\nSeek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!", objectives = "Blow Helya's Horn and direct the kvaldir to destroy the three Legion portals.", progress = "Did the kvaldir answer your call, <name>?", completion = "Well done, <name>. The kvaldir will be useful tools in the battles to come." }
WordHunterWoW_QuestEN[45636] = { title = "Dual Boss - Free Attempt Used [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[45637] = { title = "Sandworm Meat", description = "", objectives = "Gettin' de colossi to wake up takes a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind da taste.", progress = "Gettin' de colossi to wake up takes a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind da taste.", completion = "Many thanks, friend.\n\nFor the Horde!" }
WordHunterWoW_QuestEN[45638] = { title = "Crunchy Spider Legs", description = "", objectives = "We need meat - any kind of meat - to feed de colossi. And there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", progress = "We need meat - any kind of meat - to feed de colossi. And there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", completion = "With your help, the Horde may win dis ting." }
WordHunterWoW_QuestEN[45639] = { title = "Chilled Meat", description = "", objectives = "De beasts of Northrend are big, heavy, and full of meat. Go find sometin' we can feed to the colossi.", progress = "De beasts of Northrend are big, heavy, and full of meat. Go find sometin' we can feed to the colossi.", completion = "This will work just fine. De Horde thanks you, bruddah." }
WordHunterWoW_QuestEN[45640] = { title = "Crocolisk Tails", description = "", objectives = "De crocolisks of Uldum are known for bein' bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", progress = "De crocolisks of Uldum are known for bein' bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", completion = "Keep the meat deliveries comin', <name>. We need all we can get." }
WordHunterWoW_QuestEN[45641] = { title = "Raw Tiger Steaks", description = "", objectives = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", progress = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", completion = "Excellent hunting, <class>." }
WordHunterWoW_QuestEN[45642] = { title = "Raw Clefthoof Meat", description = "", objectives = "Gorchuk tells me that the old <race> clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", progress = "Gorchuk tells me that the old <race> clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", completion = "Look at that mountain of meat. You done de Horde proud, <name>." }
WordHunterWoW_QuestEN[45643] = { title = "Lean Shanks", description = "", objectives = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in de Broken Isles.", progress = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in de Broken Isles.", completion = "You make your Warchief proud. For da Horde!" }
WordHunterWoW_QuestEN[45644] = { title = "Oh Doloria, My Sweet Doloria", description = "What ho! We are quite the dashing pair of adventurers, aren't we?\n\nNow that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria. Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky!\n\nIt must be Dalaran. Quickly, squire! Mount up and meet me at Dalaran's famous inn. Make haste!", objectives = "Seek out Doloria in the Legerdermain Lounge in Dalaran.", completion = "Blast, I didn't think he would find me again so fast." }
WordHunterWoW_QuestEN[45645] = { title = "A Fool's Errand", description = "Oh yea sure, I'm, um, held here against my, you know, will, or something.\n\nLook bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth.\n\nI've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom.\n\nTake your time, don't get hurt. Much.", objectives = "Kill \"Hill Bandits\" to find Doloria's stolen \"Jewelry\" and buy her \"release\".", progress = "Kill \"Hill Bandits\" to find Dolorias stolen \"Jewelry\" and buy her \"release\"", completion = "<Doloria gives you a sly wink from behind her mask>\n\nUh, no, haven't seen her for a few days, not sure who you're talking about." }
WordHunterWoW_QuestEN[45647] = { title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", objectives = "Rescue 8 squads of Captured Warriors.", progress = "Have we found them all?", completion = "Our soliders will be back in action soon, and the Felrage naga will think twice before messing with us again!" }
WordHunterWoW_QuestEN[45648] = { title = "Missing in Action: Lord Darius Crowley", description = "Are you familiar with Lord Darius Crowley? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. \n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", objectives = "Search for Lord Darius Crowley.", completion = "Thanks. I was ambushed by a dozen naga and skrog! At least I took quite a few down before they overwhelmed me..." }
WordHunterWoW_QuestEN[45649] = { title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", objectives = "Rescue 8 squads of captured warriors.", progress = "Have we found them all?", completion = "Our soliders will be back in action soon, and the Felrage naga will think twice before messing with us again!" }
WordHunterWoW_QuestEN[45650] = { title = "Operation Felrage", description = "I am very concerned to discover naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", objectives = "Kill Warlord Kaz'jatar and Felbeard.", progress = "Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", completion = "With their leaders defeated, the Felrage naga won't be launching any more raids for awhile! Still, we should keep an eye on them in the future." }
WordHunterWoW_QuestEN[45651] = { title = "The Ruins of Ahn'Qiraj: Ossirian", description = "", objectives = "" }
WordHunterWoW_QuestEN[45652] = { title = "A \"Humble\" Request", description = "{class}t, we've received a... visitor. She orders entry, but the guards will not let her pass without approval.\n\nPlease head up to the overlook as soon as you are able.", objectives = "Meet your visitor at Storm's Eye Overlook.", progress = "Our \"guest\" is waiting for you. You may want to hurry.", completion = "You're in charge here?" }
WordHunterWoW_QuestEN[45653] = { title = "Kill it with Fire!", description = "", objectives = "" }
WordHunterWoW_QuestEN[45654] = { title = "Ahn'Qiraj: C'Thun", description = "", objectives = "" }
WordHunterWoW_QuestEN[45655] = { title = "The Colossus of Ashi", description = "", objectives = "" }
WordHunterWoW_QuestEN[45656] = { title = "Lesser Wind Stones", description = "", objectives = "" }
WordHunterWoW_QuestEN[45657] = { title = "Silithyst", description = "", objectives = "" }
WordHunterWoW_QuestEN[45674] = { title = "The Colossus of Regal", description = "", objectives = "" }
WordHunterWoW_QuestEN[45675] = { title = "The Colossus of Zora", description = "", objectives = "" }
WordHunterWoW_QuestEN[45682] = { title = "Looted Rogue Vault", description = "", objectives = "" }
WordHunterWoW_QuestEN[45694] = { title = "Arachnicide", description = "", objectives = "" }
WordHunterWoW_QuestEN[45706] = { title = "The Power of Thousands", description = "I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition.\n\nThe Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.", objectives = "Take Magatha's portal and meet her in Thousand Needles.", completion = "Let's not keep my tribe waiting." }
WordHunterWoW_QuestEN[45723] = { title = "The Crone's Wrath", description = "These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.", objectives = "Defeat 15 demons on Darkcloud Pinnacle.", completion = "Fel blood has never been sweeter." }
WordHunterWoW_QuestEN[45724] = { title = "Snakes and Stones", description = "When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone.\n\nWhile death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone... such an artifact of power belongs in my hands, not theirs. We must split up to find them.\n\nFor the world's sake, do be careful. I don't need you clumsily destroying everything.", objectives = "Find either the Doomstone or Arikara on Darkcloud Pinnacle.", progress = "Greetings, Farseer. What have you found?", completion = "I reclaimed Arikara. Did you find the Doomstone?" }
WordHunterWoW_QuestEN[45725] = { title = "Breaking Chains", description = "The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.", objectives = "Free 8 Captured Grimtotem from Prison Cages.", completion = "The Legion cannot break the Grimtotem." }
WordHunterWoW_QuestEN[45726] = { title = "The Tainted Marsh", description = "I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic!\n\nI will rework this fel totem to draw out the fel energies they infused in those spirits.\n\nPlease, cure what spirits you can, perhaps it will even give them some peace.\n\nIf you want, I can even send you there!", objectives = "Drain the fel energies from the spirits of the Blind Marshlands.", progress = "I'm tired of these monsters abusing everything around them!", completion = "You've done those souls a great favor. I hope they find peace.\n\nLet's cut off these experiments at the source now." }
WordHunterWoW_QuestEN[45727] = { title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", objectives = "Speak to Archmage Khadgar in Dalaran.", completion = "Excellent work, <name>. We still have a long road ahead of us to rid this world of the Legion, but this brings us one step closer." }
WordHunterWoW_QuestEN[45728] = { title = "Legion Assault: Thunder Totem", description = "", objectives = "" }
WordHunterWoW_QuestEN[45729] = { title = "Sandworm Meat", description = "", objectives = "Convincing the giant colossi of Silithus to wake up requires a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind the taste too much!", progress = "Convincing the giant colossi of Silithus to wake up requires a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind the taste too much!", completion = "Many thanks, friend.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[45730] = { title = "Crunchy Spider Legs", description = "", objectives = "We need meat - any kind of meat - to feed the colossi... and there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", progress = "We need meat - any kind of meat - to feed the colossi... and there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", completion = "With your help, the Alliance may win this thing." }
WordHunterWoW_QuestEN[45731] = { title = "Chilled Meat", description = "", objectives = "The beasts of Northrend are big, heavy, and full of meat. Go find something we can feed to the colossi.", progress = "The beasts of Northrend are big, heavy, and full of meat. Go find something we can feed to the colossi.", completion = "This will work just fine. The Alliance thanks you." }
WordHunterWoW_QuestEN[45732] = { title = "Crocolisk Tails", description = "", objectives = "The crocolisks of Uldum are known for being bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", progress = "The crocolisks of Uldum are known for being bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", completion = "Keep the meat deliveries coming, <name>. We need all we can get." }
WordHunterWoW_QuestEN[45733] = { title = "Raw Tiger Steaks", description = "", objectives = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", progress = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", completion = "Excellent hunting, <class>." }
WordHunterWoW_QuestEN[45734] = { title = "Raw Clefthoof Meat", description = "", objectives = "I remember reading that the old orc clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", progress = "I remember reading that the old orc clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", completion = "Look at that mountain of meat. You have done the Alliance proud, <name>." }
WordHunterWoW_QuestEN[45735] = { title = "Lean Shanks", description = "", objectives = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in the Broken Isles.", progress = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in the Broken Isles.", completion = "You make your King proud. For the Alliance!" }
