WordHunterWoW_QuestEN[45746] = { title = "Salvation", description = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.\n\nTake this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Manaroot Salve on fel-infected animals." }
WordHunterWoW_QuestEN[45747] = { title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", objectives = "Bring the Cinder of Cynders to Warlord Gorchuk in Silithus.", progress = "Have you brought me trophies of war?", completion = "Well done, <race>. For the Horde!" }
WordHunterWoW_QuestEN[45748] = { title = "Pearl of Fathoms", description = "The pearl is immaculately smooth, and surprisingly dense.", objectives = "Bring the Pearl of Fathoms to Warlord Gorchuk in Silithus.", progress = "I'm not in the market for jewelry, <class>...", completion = "Oh, I see. This is a trophy of battle.\n\nWe will add it to the many treasures you and your fellow adventurers have brought. For the Horde!" }
WordHunterWoW_QuestEN[45749] = { title = "Salt of Shards", description = "The Abyssal Lord left behind a small pile of faintly-iridescent sand.", objectives = "Bring the Salt of Shards to Warlord Gorchuk in Silithus.", progress = "What do you have there? That isn't Silithyst, is it?", completion = "Ahh, the trophy of an epic battle. Well fought, <class>!" }
WordHunterWoW_QuestEN[45750] = { title = "Song of Zephyrs", description = "A swirling essence coalesces at the feet of the Duke.", objectives = "Bring the Song of Zephyrs to Warlord Gorchuk in Silithus.", progress = "You wrote me a song? How thoughtful.", completion = "Ah, I see, it is a hard-earned reward from one of your many battles. Well done, <class>!" }
WordHunterWoW_QuestEN[45751] = { title = "Coreforged Sigil of Skaldrenox", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.", objectives = "Bring the Coreforged Sigil of Skaldrenox to Warlord Gorchuk in Silithus.", progress = "What news from the battlefield, <race>?", completion = "This is an impressive find indeed. The Abyssal High Council do not part with their sigils easily." }
WordHunterWoW_QuestEN[45752] = { title = "Glimmering Sigil of Whirlaxis", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.", objectives = "Bring the Glimmering Sigil of Whirlaxis to Warlord Gorchuk in Silithus.", progress = "You've returned from battle, <race>. Any trophies to share?", completion = "To wrest a sigil from one of the Abyssal High Council is a feat worthy of praise. For the Horde!" }
WordHunterWoW_QuestEN[45753] = { title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", objectives = "Bring the Diamondine Sigil of Kazum to Warlord Gorchuk in Silithus.", progress = "A diamond ring? Why... why are you bringing this to me?", completion = "Ah, a sigil. From the Abyssal High Council, no less!\n\n<Warlord Gorchuk wipes a bead of sweat from his brow.>\n\nI... I had assumed that it was... that you were... oh, never mind.\n\nFor the Horde!" }
WordHunterWoW_QuestEN[45754] = { title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", objectives = "Bring the Tidal Sigil of Skwol to Warlord Gorchuk in Silithus.", progress = "What have we here?", completion = "A sigil from the Abyssal High Council? You've outdone yourself today, <race>.\n\nFor the Horde!" }
WordHunterWoW_QuestEN[45755] = { title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", objectives = "Bring the Cinder of Cynders to Field Marshal Snowfall in Silithus.", progress = "Have you brought me trophies of war?", completion = "Well done, <race>. For the Alliance!" }
