WordHunterWoW_QuestEN[45761] = { title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", objectives = "Bring the Diamondine Sigil of Kazum to Field Marshal Snowfall in Silithus.", progress = "A diamond ring? Why... why are you bringing this to me?", completion = "Ah, a sigil. From the Abyssal High Council, no less!\n\n<Field Marshal Snowfall wipes a bead of sweat from his brow.>\n\nI... I had assumed that it was... that you were... oh, never mind.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[45762] = { title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", objectives = "Bring the Tidal Sigil of Skwol to Field Marshal Snowfall in Silithus.", progress = "What have we here?", completion = "A sigil from the Abyssal High Council? You've outdone yourself today, <race>.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[45763] = { title = "Demonic Disruption", description = "While scouting on the Broken Shore, we have stumbled upon something quite unsettling.\n\nThe Legion is attempting to harness the powers of Azeroth's elements. What is more, they are succeeding.\n\nWe must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.", objectives = "Speak to Farseer Nobundo to go to the Broken Shore, then meet Therazane at the Garrison of the Fel.", completion = "The Legion is forcing Azeroth to bend to its will. We cannot allow this any longer!" }
WordHunterWoW_QuestEN[45764] = { title = "Restoring Equilibrium", description = "Kor'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that'ss even possible...\n\nIt hass also begun listing to one side - rather comically, I might add. For some reason, Kor'vass doesn't find this nearly as entertaining as she should.\n\nAnyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss.\n\nSay the word and I will direct a squadron of illidari batriderss to accompany you. I'd come too, but...", objectives = "Obtain 3 Stabilizing Crystals.", progress = "Have you secured the materialss for repairing the Fel Hammer, <name>?", completion = "It'ss a shame the batriderss didn't make it. Even more reason to blast the hell out of the Legion as soon as the Fel Hammer'ss weaponss core iss operational again." }
WordHunterWoW_QuestEN[45765] = { title = "Brothers and Sisters", description = "Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.", objectives = "Heal 8 Injured Shaman  in Garrison of the Fel.", progress = "Rock may chip, but it does not bleed as flesh does.", completion = "I provided cover as the weaker of your people retreated. They will return to the Maelstrom safely." }
WordHunterWoW_QuestEN[45766] = { title = "Albino Elderhorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[45767] = { title = "Elemental Cores", description = "The eredar here are abusing the power of all of Azeroth's elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element.\n\nDo not allow the Legion to continue abusing our world. Kill them and take the sources of their power.", objectives = "Collect 3 Fire Power Cores, 3 Water Power Cores, 3 Earth Power Cores, and 3 Air Power Cores.", progress = "Nobody should force the elements to bend to their will. Show the Legion that their understanding is flawed.", completion = "It seems the Doomstone is pulsating with energy." }
WordHunterWoW_QuestEN[45769] = { title = "Conflagration", description = "That fiend! Up on the hill, a demon who calls himself \"The Flameripper\" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his.\n\nHe is extremely powerful, Farseer. You must take him down, whatever the cost!", objectives = "Kill Barastagax the Flameripper.", completion = "Ah, you've awoken. I have heard tale of what happened." }
WordHunterWoW_QuestEN[45770] = { title = "Stirring in the Shadows", description = "We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme.\n\nWhen it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use.\n\nThen it's just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare's mount, Shadowmane.\n\nTravel to the service gate of Stratholme when you're ready.", objectives = "Meetup with Lord Grayson Shadowbreaker in Stratholme. Once inside, locate the remains of Lord Rivendare and his mount and perform the ritual to claim it as your own.", progress = "Your mount is within our reach, Highlord. I only pray Stratholme still has an ample supply of holy water.", completion = "That was quite the encounter, wouldn't you say Highlord <name>? Reminds me of my glory days.\n\nNevertheless we'll be keeping a more watchful eye on Stratholme from now on. But that's not important right now.\n\nWe should move on to the ceremony and have you claim your prize!" }
WordHunterWoW_QuestEN[45771] = { title = "A Time for Everything", description = "Our order is recovering thanks to your quick actions, Grandmaster. \n\nThere is just one more monk we need to attend to before it is too late!", objectives = "Give the Curative Brew to Iron-Body Ponshu.", completion = "Grandmaster <name>, these old bones grow weary. Our future depends on you to continue the fight against the Legion.\n\nSo long as you remain a beacon of light in the darkness, hope remains!" }
WordHunterWoW_QuestEN[45773] = { title = "7.2 Class Hall - Maximillian of Northshire - Aqcuisition - Track Mail Sent", description = "", objectives = "" }
WordHunterWoW_QuestEN[45775] = { title = "FLAG (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[45776] = { title = "Keys are a Crutch", description = "", objectives = "" }
WordHunterWoW_QuestEN[45785] = { title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", objectives = "Report to Warlord Gorchuk in Silithus.", completion = "And who are you? <name>?\n\nAhh... yes, I believe I've heard mention of you before. Welcome to Silithus, <name>.\n\nToday, we celebrate our heritage as sons of Kalimdor. Furthermore, we prove that the Horde will always grind those puny Alliance into the ground.\n\nAre you with me?" }
WordHunterWoW_QuestEN[45786] = { title = "Feast of the Hounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[45787] = { title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", objectives = "Report to Field Marshal Snowfall in Silithus.", completion = "And who are you? <name>?\n\nAhh... yes, I believe I've heard mention of you before. Welcome to Silithus, <name>.\n\nToday, we celebrate the fabled war history of Kalimdor. Furthermore, we prove that the Alliance will always show the Horde their inferiority.\n\nAre you with me?" }
WordHunterWoW_QuestEN[45788] = { title = "The Speaker Awaits", description = "High Priest, we've received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself!\n\nWhat could he want from our order? You'd best head back to Netherlight, we'll hold down the front here.", objectives = "Speak with Betild Deepanvil in Netherlight Temple.", completion = "Thank ye for coming so quickly, High <class>. King Magni, or I suppose I should say 'The Speaker,' thinks he's found a hidden Titan vault!" }
WordHunterWoW_QuestEN[45789] = { title = "The Sunken Vault", description = "'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth.\n\nThe voice is telling 'im there's a lost Titan vault out there, near the Maelstrom. We dun know what's inside, but he's got tha feelin' it's got somethin' ta do with the Light, and you!\n\nBrann's got a vessel waitin' for ye, off the coast of Azsuna. Of course, I'll be accompanying ye as well, for cataloguing purposes. Can't go and let a chance like this go to waste!", objectives = "Take Brann's vessel in Azsuna to the Sunken Vault.", progress = "Ta be one o' tha first to step foot in a lost Titan vault, it gives me tha chills!", completion = "Tis our greatest honor ta present ye with this steed, High <class>. An' thank ye for leading us, ye are truly blessed by the Light, an' so are all of us for havin' ye." }
WordHunterWoW_QuestEN[45790] = { title = "Champion: Almai", description = "", objectives = "I will miss Brewmaster Blanche. She taught me to follow my dreams.\n\nAnd I have always wanted to study Mistweaving...\n\nGrandmaster <name>. If you will have me, I will defend you and our order from all that wish us harm." }
WordHunterWoW_QuestEN[45791] = { title = "War Materiel", description = "", objectives = "" }
WordHunterWoW_QuestEN[45792] = { title = "Occultist Onslaught", description = "", objectives = "" }
WordHunterWoW_QuestEN[45793] = { title = "Occultist Onslaught", description = "", objectives = "" }
WordHunterWoW_QuestEN[45794] = { title = "Informing the Council", description = "I'll deal with this prisoner, but you should head back to Dreadscar Rift. \n\nLet the others know what we've discovered. We will need their help dealing with Kanrethad on the Broken Shore.", objectives = "Return to Shinfel Blightsworn in Dreadscar Rift.", completion = "Thank you for bringing me news of Jubeka. It could not have come at a better time.\n\nWe've received information on Kanrethad's whereabouts." }
WordHunterWoW_QuestEN[45795] = { title = "Presence of Power", description = "The demons appear to be harnessing an ancient power within the Temple itself. They've managed to twist and corrupt these sacred grounds with fel magic.\n\nWe must remove the demonic presence before we press our final advance.", objectives = "Repel the Legion threat from the Temple of a Thousand Lights, then Slay Portal-Keeper V'thaal and Zor'thaduun.", progress = "Can you feel the immense energy?", completion = "Our fight doesn't end here, <name>." }
WordHunterWoW_QuestEN[45796] = { title = "Destroying the Nest", description = "We have to put an end to Tugar's plot. These abominations must be destroyed, as well as their source!\n\nI think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place.\n\nGo there and stop their fel monster production at its source!", objectives = "Enter the Feltotem Caverns and ruin Tugar's plot.", progress = "A tough fight to be sure, have you prevailed?", completion = "You have saved Thunder Totem and we owe you yet another debt.\n\nIt's a shame that Tugar wasn't there. As long as he lives, we are in danger.\n\nI will do everything I can to find him, and then we will finish this... together." }
WordHunterWoW_QuestEN[45797] = { title = "Playing with Green Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[45798] = { title = "War'zuul the Provoker", description = "There'ss some obnoxious demon lord up there who's been yelling for hourss. \n\nWould you please shut him up already? I'm getting a terrible headache!", objectives = "Kill War'zuul the Provoker.", completion = "It'ss about time you shut that demon up. Thanksss..." }
WordHunterWoW_QuestEN[45799] = { title = "A Shrouded Path Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[45801] = { title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost." }
WordHunterWoW_QuestEN[45802] = { title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost." }
