WordHunterWoW_QuestEN[45813] = { title = "Where Art Thou, My Sweet", description = "What poor fate! Here we are with the jewelry to buy my beloved's freedom, and she has disappeared! We must inquire of the patrons of this fine establishment. Perhaps they know what befell her.", objectives = "Help to maintain Doloria's \"illusion\" and ask around the Inn to see where Doloria disappeared to.", completion = "Well, she has been taken, but we shall never rest. Join me as my Follower, lead my troops, perform missions for me! Together we will find her!" }
