WordHunterWoW_QuestEN[45833] = { title = "The Pirate's Bay", description = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.\n\nWe've received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man's Bay in Azsuna.", objectives = "Meet up with Tess Greymane and Tethys at Dead Man's Bay in Azsuna.", completion = "Straighten up, Shadowblade. We've got work to do." }
WordHunterWoW_QuestEN[45834] = { title = "Stolen Souls", description = "Odyn's worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen.\n\nNow, you can restore them to their rightful places. Destroy the soul fonts to release them!", objectives = "Free 15 stolen souls.", completion = "With the Valarjar leading the vanguard, our offensives will be glorious!" }
WordHunterWoW_QuestEN[45835] = { title = "False Orders", description = "As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time.\n\nPlant the orders in the marked locations. You should see the results rather quickly.", objectives = "Plant the False Orders in the marked locations.", completion = "They ran right past us on their way out." }
WordHunterWoW_QuestEN[45836] = { title = "Jorach's Calling", description = "And with that, the first phase of the plan is complete. It's best we return to Jorach and bring him the news.", objectives = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", completion = "Welcome back, Shadowblade. I assume you've retrieved the gunpowder?" }
WordHunterWoW_QuestEN[45837] = { title = "Creeping Fel", description = "", objectives = "" }
WordHunterWoW_QuestEN[45838] = { title = "Assault on Azsuna", description = "The demons strike at the heart of our existence, posing a threat to all who inhabit our lands.\n\nRemove the threat before it is too late.", objectives = "Repel the Burning Legion forces throughout Azsuna.", completion = "I'm afraid our fight has only brought us so far. We must press our attack before the Legion advances beyond their stronghold within the Temple of a Thousand Lights!" }
WordHunterWoW_QuestEN[45839] = { title = "Assault on Stormheim", description = "The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim!\n\nChampion, now is your call to valor! Find the forces of the Legion and eradicate them!", objectives = "Repel the Burning Legion forces throughout Stormheim.", completion = "Just beyond these cliffs, the forces of the Legion are gathering for their assault. For every moment that passes their number grows.\n\nWe must strike soon before we are overwhelmed!" }
WordHunterWoW_QuestEN[45840] = { title = "Assault on Highmountain", description = "In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. \n\nThe demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create.\n\nRise to the occasion, {name}. The time has come to stand against the Burning Legion!", objectives = "Repel the Burning Legion forces throughout Highmountain.", completion = "My apologies, <name>. I hope Aviash and I did not offend you. One cannot be too careful during times like these." }
WordHunterWoW_QuestEN[45841] = { title = "A Triumphant Report", description = "You should return to your Kirin Tor. I have no doubt they will want to hear the good news!", objectives = "Speak with Archmage Modera in Dalaran.", completion = "I am relieved that you have dealt with immediate threat. We barely have enough resources for the Broken Shore as it is!\n\nStill we have something for you..." }
WordHunterWoW_QuestEN[45842] = { title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", objectives = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel.", progress = "Are you ready?", completion = "We hope the increased power to your weapon will prove useful on the Broken Shore and beyond." }
WordHunterWoW_QuestEN[45843] = { title = "Dark Omens", description = "We won't be able to defeat Kruul alone.\n\nOnce the portal has stabilized I will send word so we can bring the Highlord to justice.\n\nIn the meantime, you should inform the Kirin Tor of Vazuun's death - and Kruul's return.", objectives = "Speak with Archmage Modera in Dalaran.", completion = "Any luck out there?" }
WordHunterWoW_QuestEN[45844] = { title = "Avocation of Antonidas", description = "Archmage Kalec has requested your presence back in the Hall of the Guardian. He's discovered something he wishes to urgently speak with you about.\n\nPlease see him at your earliest convenience.", objectives = "Speak with Archmage Kalec in the Hall of the Guardian.", completion = "Archmage, I've found something you may be interested in. An old journal of the late Archmage Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical specialization.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces." }
WordHunterWoW_QuestEN[45845] = { title = "Burning Within", description = "The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core.\n\nHowever, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire.\n\nPerhaps you should speak with Khadgar and find out what became of the disc.", objectives = "Speak with Khadgar about the Tri-Disc of Fire. Follow his instructions after you speak with him.", progress = "Was Khadgar able to remember what he did with the piece?", completion = "You've recovered it! And it is as Antonidas wrote, still surging with great fire magic!" }
WordHunterWoW_QuestEN[45846] = { title = "Chilled to the Core", description = "The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc.\n\nIf I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided.\n\nHopefully he knows where to find the disc.", objectives = "Speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.", progress = "After the devastation that befell Dalaran's original home, who knows where that disc may be.", completion = "Ogres took it? Those beasts will grab anything they can I suppose.\n\nRegardless, it's excellent you were able to find it." }
WordHunterWoW_QuestEN[45847] = { title = "Close to Home", description = "The third piece of the disc was infused with Antonidas' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it.\n\nHe wrote that he gave the piece to Archmage Celindra...\n\nIsn't she the portal trainer here in Dalaran? She must know where the piece is!\n\nQuickly, go speak with her.", objectives = "Speak to Archmage Celindra about the Tri-Disc of the Arcane here in Dalaran.", progress = "Did she have it?", completion = "To think it was right here in Dalaran the whole time." }
WordHunterWoW_QuestEN[45848] = { title = "Fit For a Pirate", description = "", objectives = "Squawk! Tethys is lame! Bad pirate! bad pirate!\n\n<name> better pirate, raaaaawk! Go with you now!" }
