WordHunterWoW_QuestEN[45883] = { title = "The Firelord's Offense", description = "Smolderon calls from across the battlefield, shaman. Now it is his realm being violated.\n\nIt seems urgent. I will clean up here.", objectives = "Report to Firelord Smolderon in Cinder Run.", completion = "I will not allow such insolence!" }
