WordHunterWoW_QuestEN[45971] = { title = "Infernal Phenomena", description = "Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will.\n\nHow dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life.\n\nSabotage their foolish rituals. Crush them! Show them Azeroth's true power!", objectives = "Interrupt 3 Infernal Rituals.", progress = "The earth is my domain, NOT the Legion's!", completion = "I laughed as their infernals crumbled. They return to Azeroth, as they belong." }
WordHunterWoW_QuestEN[45972] = { title = "The Accursed Thicket", description = "There is one last task for you and the Doomstone. Thunderaan will explain all.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Thunderaan." }
