WordHunterWoW_QuestEN[45974] = { title = "An Urgent Warning", description = "<The soldier is wan and wounded, obviously in tremendous pain.>\n\nBeen held prisoner... since the assault on... the Broken Shore...\n\n<He shudders.>\n\nThe demons... th-they are gathering... preparing...\n\nHad to escape... to warn you. They must... be stopped!", objectives = "Speak to Lord Maxwell Tyrosus", completion = "Greetings, Highlord. I've just been informed about the wounded soldier who escaped from the Broken Shore.\n\nWhat he must have endured..." }
WordHunterWoW_QuestEN[45975] = { title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Tyrosus turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", objectives = "Use the Scouting Map and complete the mission, \"Menace on the Broken Shore\".", completion = "Grim tidings indeed.\n\nI suggest we continue sending our champions to scout out the dangers that await." }
