WordHunterWoW_QuestEN[46000] = { title = "Arming Dalaran", description = "Kathra'natir is powerless to stop us from harnessing his energy within the Nightborne Soulstone. We have been lucky thus far - our allies have kept news of the sabotage from spreading. \n\nWe should repair Dalaran's weapons array immediately while luck is still on our side.\n\nOh - the weapon platform is a bit inaccessible. I trust you are not afflicted by a fear of heights? I will open a portal.", objectives = "Travel to the Dalaran Spire via Aethas' portal.", progress = "Use the Control Crystal to activate the Soulstone!", completion = "Well done, Archmage <name>! Dalaran can defend herself once again.\n\nFor all of our sakes, let us hope that the shields keeping Kathra'natir imprisoned do not fail before we are able to find a safer solution." }
