WordHunterWoW_QuestEN[46020] = { title = "Crystal Containment", description = "Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic.\n\nIf any should break, the energy inside would find its way back to our friend. I shouldn't need to tell you how devastating it would be if that were to happen.\n\nI will gather the crystals and meet you back at Dreadscar Rift.", objectives = "Meet Jubeka Shadowbreaker in Dreadscar Rift.", completion = "The crystals will be safe here, with each of the council members watching over them.\n\nKanrethad is still recovering, but is well enough to speak." }
