WordHunterWoW_QuestEN[46034] = { title = "Champion: Aelthalyste", description = "", objectives = "All these priests? They report to you? It's astonishing, really.\n\nI have only one Roland, and it seems you have hundreds!\n\nI think we will get along well, <name>. Very well, indeed.\n\nAllow me to stay, and in return, I will offer you my services." }
WordHunterWoW_QuestEN[46035] = { title = "End of the Risen Threat", description = "Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you.\n\nI'm prepared to teleport you to his location, but there's a snag.\n\nIn order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.", objectives = "Defeat Lord Erdris Thorn. Speak with War Councilor Victoria to be teleported to Jarod Shadowsong's location.", completion = "Another crisis averted! Your effectiveness is without compare." }
