WordHunterWoW_QuestEN[46043] = { title = "Champion: Aethas Sunreaver", description = "", objectives = "Archmage, the events of the past have long weighed heavily upon me. While I do not regret my actions, I do regret what happened. If I could go back and change things...\n\nI hope in time the Kirin Tor - indeed, all of Azeroth - will better understand my loyalties. Thanks to you, crisis has been averted. Please accept my enduring gratitude." }
WordHunterWoW_QuestEN[46044] = { title = "Champion: Thisalee Crow", description = "", objectives = "Look, Archdruid, don't get me wrong. I love Aviana. She's my ancient! But she's a little too passive for me to follow around all the time.\n\nYou, on the other hand? You're the real deal! I want to be in the fray, ruining some demon's day!\n\nSo? Will you take me with you?" }
WordHunterWoW_QuestEN[46045] = { title = "Champion: Nerus Moonfang", description = "", objectives = "I know I have much to answer for.\n\nAlthough you have freed my family from their curse, nothing can take away the pain my mistakes have caused them. \n\nDelas has done well to devote herself to the Silver Hand. Do not let my past reflect poorly on her.\n\nI'd like to follow her lead, and lend my aid to your order." }
WordHunterWoW_QuestEN[46046] = { title = "Life's a Lich", description = "", objectives = "" }
WordHunterWoW_QuestEN[46047] = { title = "Champion: Kanrethad Ebonlocke", description = "", objectives = "Although my recollection of recent events is still a bit hazy, the power you displayed when dispatching Rezara was something I could never forget.\n\nIt seems fitting that the council chose you as its leader in my absence.\n\nRest assured, I have no desire to challenge their decision. I owe you my life.\n\nLet me serve you and the council. There is much we can learn from each other." }
WordHunterWoW_QuestEN[46048] = { title = "Champion: Nighthuntress Syrenne", description = "", objectives = "Tell me, <name>, are all those among your ranks as dedicated as their leader?\n\nI've been reluctant to trust outsiders, but you and I aren't so different, are we? We're both willing to go to great lengths to protect the things we care about. Our goals seem to align in that regard.\n\nI would like to lend my aid to you and your hunters, if you'll allow it." }
WordHunterWoW_QuestEN[46049] = { title = "A Gift From Your Tadpole", description = "", objectives = "<Your tadpole has prepared a gift for you. What could be inside?>" }
WordHunterWoW_QuestEN[46050] = { title = "Champion: Minerva Ravensorrow", description = "", objectives = "Look, I may be dead and my lungs may serve no purpose, but raising Daumyr to undeath was like a breath of fresh air for me. I ask that you continue to take me under your guidance. Bring me to the battlefield again! I will scatter the bones of any demon that so much as looks at me." }
WordHunterWoW_QuestEN[46051] = { title = "FLAG - March of the Tadpoles Bit 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[46052] = { title = "FLAG - March of the Tadpoles Bit 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[46053] = { title = "FLAG - March of the Tadpoles Bit 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[46054] = { title = "FLAG - March of the Tadpoles Bit 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[46055] = { title = "FLAG - March of the Tadpoles Bit 05", description = "", objectives = "" }
WordHunterWoW_QuestEN[46057] = { title = "Champion: Magatha Grimtotem", description = "", objectives = "You are a foolish child. You think you have great power, but you know nothing. The Doomstone should be used for the greatness it can accomplish! It will waste away sitting in the Maelstrom.\n\nPerhaps it was a mistake coming here. Nobundo requests that the Grimtotem stay. I stay for my own reasons, not because he asked. If you need me or my warriors to earn our keep, we will oblige.\n\nBut remember your place." }
WordHunterWoW_QuestEN[46058] = { title = "Champion: Lilian Voss", description = "", objectives = "You made quick work of those demons, and I hope you do the same to many more. So long as the Legion extends their influence on our world, they will continue to corrupt our people as well.\n\nI would like to continue to work with you to end this madness. My blades are yours, Shadowblade." }
WordHunterWoW_QuestEN[46059] = { title = "Champion: Tess Greymane", description = "", objectives = "You've proven your expertise to me many times over, Shadowblade. While my colleagues have already pledged their service to you, I took a step back. Though all rogues step in the shadows, it is of vital importance that my status remains truly secret.\n\nHowever, the threat is too great. We are so close to taking the Legion down... and I want to take on a greater role in it." }
WordHunterWoW_QuestEN[46060] = { title = "Salvation", description = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.\n\nTake this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.", objectives = "Use the Manaroot Salve on fel-infected animals.", completion = "You risked your life freeing those animals from a life worse than death. I commend you, <name>." }
WordHunterWoW_QuestEN[46061] = { title = "Adopt a Tadpole", description = "One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I'm not sure why this tradition persists, as it usually results in heavy damage to buildings and food stores.\n\nI usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.", objectives = "Select your favorite Winterfin tadpole and beckon it to follow you.", completion = "Glrm. Mrr glrg." }
WordHunterWoW_QuestEN[46062] = { title = "A Tadpole's Request", description = "Glrrrr! Mrr, mrr, glrrgli!\n\n<Your favorite little tadpole is getting reckless. Maybe he might like some clams?>", objectives = "Obtain 10 Winterfin Clams.", progress = "Mrglr?", completion = "Glrrrrms!" }
WordHunterWoW_QuestEN[46063] = { title = "The Wailing Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[46064] = { title = "The Ways of the World", description = "Mrrga!\n\n<Your tadpole cowers and hides, as he observes the shadowy figure of a large orca passing through the Westrift.>\n\nMrrga... Mrrga...", objectives = "Slay Mrrga.", progress = "Mrrga mr?", completion = "Mrrga mr. Gll-mrrr!" }
WordHunterWoW_QuestEN[46065] = { title = "An Impossible Foe", description = "{name}! We have just received word from the Council of Six. They have found Agatha!\n\nModera asked that she be able to brief you through this image crystal.  \n\nGood luck!", objectives = "Speak with War Councilor Victoria to be teleported to the Imp Mother's Den and defeat Agatha.", completion = "News has reached me of Agatha's demise, as well as her plot to infiltrate the Kirin Tor. If it weren't for your swift action, I fear the damage her sayaad could've done would be irreparable. \n\nMy mages are working to hunt down any of Agatha's remaining allies, but the real victory today belongs to you, <name>.\n\nThe Kirin Tor thanks you." }
WordHunterWoW_QuestEN[46066] = { title = "I Fel Bat For You", description = "", objectives = "" }
WordHunterWoW_QuestEN[46068] = { title = "Brute Wrangling", description = "", objectives = "" }
WordHunterWoW_QuestEN[46069] = { title = "Worthy of the Title", description = "Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter.\n\nPlease seek him out at Light's Hope Chapel in your order hall at your earliest convenience.", objectives = "Speak with Lord Grayson Shadowbreaker in your order hall.", completion = "Highlord! I'd like to speak with you about obtaining a special mount..." }
WordHunterWoW_QuestEN[46070] = { title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", objectives = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", progress = "How goes the search for the barding? Find anything suitable yet?", completion = "<Grayson examines the barding.>\n\nThis is... well, a good start, Highlord. But I think it will have to be strengthened a bit." }
WordHunterWoW_QuestEN[46071] = { title = "The Hammer of Dalaran", description = "Should we wish to make this barding worthy of the steed who will bear it, we'll need to upgrade it. Right now it's just good for not getting you kicked off your mount.\n\nSpeak with Alard Schmied in Dalaran. He's a fine smith and will know how to modify this barding into something more befitting our needs.", objectives = "Speak with Alard Schmied in Dalaran.", completion = "Greetings, Highlord. What can I help you with?\n\n<You explain what you need to Alard as he looks over the barding.>\n\nI see. I can certainly help you with your upgrading this, but I'll need a few things first." }
WordHunterWoW_QuestEN[46072] = { title = "Full Fel", description = "", objectives = "" }
WordHunterWoW_QuestEN[46073] = { title = "Break Their Garrison", description = "", objectives = "" }
WordHunterWoW_QuestEN[46074] = { title = "Leather to Legendary", description = "Let's begin, shall we? I mean, I'll be doing all the work, but you get to watch!\n\n<Alard grins a wide smile at you and begins working.>", objectives = "Have Alard upgrade the barding and return with it to Lord Grayson Shadowbreaker at your order hall.", progress = "How'd it go? Was Alard able to upgrade the barding?", completion = "<Grayson examines the barding.>\n\nThis is perfect. Exactly what I expected from Alard. Now that we have everything together, there is but one task left." }
WordHunterWoW_QuestEN[46075] = { title = "Relic Hunting", description = "", objectives = "" }
WordHunterWoW_QuestEN[46076] = { title = "Restless Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[46077] = { title = "Felbound Spirits", description = "", objectives = "" }
WordHunterWoW_QuestEN[46078] = { title = "Holy: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.\n\nSpecialization: Holy Priest", objectives = "Go to Bradensbrook in Val'sharah.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten." }
WordHunterWoW_QuestEN[46079] = { title = "Aid on the Front Lines", description = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us!\n\nWe could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!", objectives = "Give aid to the wounded on the east, west, and south defense lines of Bradensbrook.", progress = "We can't take anymore losses.", completion = "You've saved many lives this day, <class>. Bradensbrook thanks you." }
WordHunterWoW_QuestEN[46080] = { title = "Quieting the Spirits", description = "An overwhelming attack on Bradensbrook is imminent. Together I believe we can blunt the spear before it is cast.\n\nWhile we are dealing with the commanders, we should put down as many unquiet spirits as we can.\n\nWith their leaders down and their numbers culled, that should give us time to find Erdris Thorn.", objectives = "Slay risen elves and spirits near Bradensbrook.", progress = "I can see you've brought a lot of \"peace\" in your day, <class>.", completion = "We realize these spirits are misguided, but we have to care about the living more than the dead at this point.\n\nThe attacks should ease off for a while." }
WordHunterWoW_QuestEN[46081] = { title = "Leather to Legendary", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I hear saber's eyes are especially sparkly. Why don't you grab one of those for this as well.", objectives = "Obtain 50 Leystone Ore and 1 Saber's Eye." }
WordHunterWoW_QuestEN[46082] = { title = "Shadowsong's Return", description = "Well our lines are doing a lot better, thanks to you. A good thing too, because we need the rest!\n\nThat being said, we noticed a big group of bigger, meaner risen coming from the farmstead. They would've given us a hard time, but that Shadowsong fellow has returned and killed them all. He's holding off reinforcements coming from the hold.\n\nI'm guessing he could use a hand. We can hold here until you and Shadowsong sort this out.", objectives = "Find Jarod Shadowsong outside Bradensbrook in Val'sharah.", completion = "I had hoped this town had found peace after what we've all been through. Somehow restless dead have been stirred into a fury. We need to stop it." }
WordHunterWoW_QuestEN[46083] = { title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", objectives = "Obtain 25 Leystone Ore and a Suramarian Sapphire.", progress = "I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", completion = "You got them! Now to upgrade your barding.\n\nNever say a blacksmith can't improve on a leatherworker's work, I always say. I mean never. I mean... well you know what I mean." }
WordHunterWoW_QuestEN[46089] = { title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", objectives = "Assassinate the infiltrating homunculi.", progress = "Your blade is not yet bloody enough.", completion = "We have shown the demons why they should truly fear the darkness. Now, Lord Ravenholdt has something for you from his personal collection." }
WordHunterWoW_QuestEN[46090] = { title = "Rare Elite 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[46091] = { title = "Rare Elite 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[46092] = { title = "Rare Elite 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[46093] = { title = "Rare Elite 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[46094] = { title = "Rare Elite 05", description = "", objectives = "" }
WordHunterWoW_QuestEN[46095] = { title = "Rare Elite 06", description = "", objectives = "" }
WordHunterWoW_QuestEN[46096] = { title = "Rare Elite 07", description = "", objectives = "" }
WordHunterWoW_QuestEN[46097] = { title = "Rare Elite 08", description = "", objectives = "" }
WordHunterWoW_QuestEN[46098] = { title = "Rare Elite 09", description = "", objectives = "" }
WordHunterWoW_QuestEN[46099] = { title = "Rare Elite 10", description = "", objectives = "" }
WordHunterWoW_QuestEN[46100] = { title = "Rare Elite 11", description = "", objectives = "" }
WordHunterWoW_QuestEN[46101] = { title = "Rare Elite 12", description = "", objectives = "" }
WordHunterWoW_QuestEN[46102] = { title = "Rare Elite 13", description = "", objectives = "" }
WordHunterWoW_QuestEN[46103] = { title = "Dread Infiltrators", description = "Shadowblade, we have received a raven with most troubling news.\n\nOne of our own, an ally that walked our very Hall of Shadows, is not who they seem.\n\nI believe Lilian has already begun dissecting their corpse. You'd best hurry.", objectives = "Speak with Lilian Voss in the Hall of Shadows.", completion = "You don't really know if an ally is an undead pawn under the control of a dreadlord until you carve into them a bit." }
WordHunterWoW_QuestEN[46104] = { title = "Arachnid Toxicity", description = "", objectives = "" }
WordHunterWoW_QuestEN[46105] = { title = "Arachnid Superiority", description = "", objectives = "" }
WordHunterWoW_QuestEN[46106] = { title = "Cutting off the Heads", description = "Erdris Thorn was a key commander of Ravencrest's forces. To hear him confusing us for the Legion fills me with a great sadness. He will be a difficult foe to defeat.\n\nWe must stop his squad leaders from forming up for a focused assault on Bradensbrook. Defeating them should delay his forces long enough for us to find and deal with him. Let us begin our grim task.", objectives = "Slay the risen squad leaders in Bradensbrook.", progress = "It is difficult to bring peace to old friends.", completion = "That should disorganize the assault for some time, but we must get to the bottom of this. I sensed a fel taint about those leaders, did you?" }
WordHunterWoW_QuestEN[46107] = { title = "Source of the Corruption", description = "There was something wrong with those three, they had a fel taint about them that was... unsettling. I believe they were somehow woken later than the other risen. Curse the Legion and their meddling!\n\nThe reinforcements are streaming out of Black Rook Hold from Heroes' Rest. We must make our way there and see if we can stop the source of these new troops.", objectives = "Find the source of the corruption at Heroes' Rest and end it.", progress = "We must end this corruption.", completion = "The attacks on Bradensbrook should relent for now. We must still deal with Lord Erdris, and soon." }
WordHunterWoW_QuestEN[46108] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nDeath to our enemies!" }
WordHunterWoW_QuestEN[46109] = { title = "Stand!", description = "", objectives = "" }
WordHunterWoW_QuestEN[46110] = { title = "Battle for Stormheim", description = "Your efforts have destroyed the Legion's forces upon Shield's Rest, yet they continue to press their assault.\n\nThere is only one way to end this - you must venture into the midst of our foe, find their commander, and remove his vile head!", objectives = "Defeat Lord Commander Alexius in Stormheim.", completion = "Well done, <name>! Well done indeed!\n\nThe Legion will rue the day they set their sights on the land of Stormheim." }
WordHunterWoW_QuestEN[46111] = { title = "Illidari Masters: Sissix", description = "", objectives = "" }
WordHunterWoW_QuestEN[46112] = { title = "Illidari Masters: Madam Viciosa", description = "", objectives = "" }
WordHunterWoW_QuestEN[46113] = { title = "Illidari Masters: Nameless Mystic", description = "", objectives = "" }
WordHunterWoW_QuestEN[46116] = { title = "On Unhallowed Grounds", description = "", objectives = "" }
WordHunterWoW_QuestEN[46118] = { title = "Larry test quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[46119] = { title = "Boon of the Builder", description = "", objectives = "<name>! Listen. You've been real good to our business. REAL good. Never thought I'd sell so many guns.\n\nWe like to reward those that patronize our establishment, so... here. Take this.\n\nSlap this puppy on your shoulderpads and go hunting for engineering supplies. You'd be surprised how many basilisks get sprockets stuck in their gullets!" }
WordHunterWoW_QuestEN[46125] = { title = "Furthering Knowledge", description = "We have learned so much already about these artifacts it is incredible. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can be used as a crash course in gaining more artifact knowledge. \n\nThis is only the first step, with more resources we should have additional courses to help you catch up on your studies.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion must fall!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!" }
WordHunterWoW_QuestEN[46126] = { title = "Fel-Corrupted Feathers", description = "", objectives = "" }
WordHunterWoW_QuestEN[46127] = { title = "Thwarting the Twins", description = "I have news from Archmage Karlain! The Kirin Tor have found Raest Magespear and can open up a portal to his location!\n\nIf you are ready to face him, I can have the mages here open the portal into the Twisting Nether.", objectives = "Speak with War Councilor Victoria to be teleported to Raest's location and defeat him.", completion = "So Raest has fallen, and in his hubris has taken his brother with him. I mourn for them both, but his brother most of all.  \n\nKaram Magespear was truly a beacon of the Light. I only hope that the stories of his sacrifices live throughout the ages. \n\nYou have done well, <name>." }
WordHunterWoW_QuestEN[46128] = { title = "Time for a Recharge", description = "", objectives = "I been thinkin' more about this whole battery thing, and how the whole process is just so... wasteful.\n\nI ain't goin' green or nothin' like that - I'm just worried about our bottom line!\n\nYou know, if one were to supercharge one of these batteries with some Blood of Sargeras, maybe cap it off with some concentrated leystone..." }
WordHunterWoW_QuestEN[46129] = { title = "Knowledge is Power", description = "Boss, you've been working every angle on the Broken Isles, infusing that ancient artifact of yours with power. But those demons won't give up, and we really need to unlock more of your weapon's potential... and I mean pronto!\n\nSlow, steady progress is one thing. But today, we need to get busy.\n\nHere's the deal. You fork over our order's resources so I can study the weapon's history, and I'll get you a way to up the value of the power you apply to that artifact.\n\nHow does that sound, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "This is a great deal, boss! Applying the resources gathered by our order will let us make big-time progress.", completion = "Learning more about your artifact weapon will sure speed up our victory over the Legion, boss.\n\nIf you supply me with order resources, I can whip up research notes on your weapon. Read 'em, and in no time you'll be taking greater advantage of the power you infuse into your artifact.\n\nLet's do this!" }
WordHunterWoW_QuestEN[46130] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nFor Azeroth!" }
WordHunterWoW_QuestEN[46131] = { title = "Knowledge is Power", description = "You are truly the scourge of the Broken Isles, wresting power from our enemies and infusing it into your ancient artifact. But we must not become complacent! Let us unlock further depths of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we will redouble our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact. And power is intoxicating.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress toward empowering your artifact and dominating our foes.", completion = "Knowledge of your artifact is the key to bending the demons to your will.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, Netherlord, and the power you infuse into your artifact will magnify.\n\nYour foes will quake in fear... as it should be!" }
WordHunterWoW_QuestEN[46132] = { title = "Knowledge is Power", description = "Durin' our campaign on the Broken Isles, ye have infused yer ancient artifact with power. But as the Legion invasion grows stronger, it's clear we need to unlock more of yer weapon's potential.\n\nThere's a time for slow, steady progress. But today, we'd best hasten our efforts.\n\nBy devotin' our order's resources to studyin' the weapon's history, we can rapidly enhance the value of the power ye apply to the artifact.\n\nWe best get started, <class>t!", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applyin' the resources gathered by our order will allow us to make quick progress toward learnin' about that weapon.", completion = "Learnin' more about yer artifact weapon'll help hasten our victory over tha Legion.\n\nIf ye supply me with order resources, I can provide research notes on yer weapon. Read 'em, and learn how to take greater advantage of the power ye infuse into yer artifact.\n\nFor Azeroth!" }
WordHunterWoW_QuestEN[46133] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have cut a swath through your enemies and infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nLet pain and suffering fall upon our enemies!" }
