WordHunterWoW_QuestEN[46140] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nThe shadows grow darker, <class>t. Let us begin.", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nWe will send the Legions back to the hell that spawned them!" }
WordHunterWoW_QuestEN[46141] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nFor Azeroth!" }
WordHunterWoW_QuestEN[46142] = { title = "Knowledge is Power", description = "In the course of trouncing foe after foe in the Broken Isles, you have infused your ancient artifact with power. But the Legion fights without honor, and to defeat them we must unlock even more of your weapon's potential.\n\nSlow, steady progress will wait for another time. Today, we must hasten the path to victory.\n\nBy devoting our order's resources to studying the weapon's history, I believe we will rapidly enhance the value of the power you apply to the artifact.\n\nGlory awaits us, <class>t!", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress. Our foes will tremble!", completion = "There is power in old tales. Learning the legend of your artifact weapon will hasten our victory over the Legion.\n\nIf you supply me with order resources, I can scribe tales of might and wonder. Read them, and the power you infuse into your artifact will echo through the Halls of Valor.\n\nFor Odyn!" }
WordHunterWoW_QuestEN[46143] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nFor Azeroth!" }
WordHunterWoW_QuestEN[46144] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must hasten our efforts.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we find the story within, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "Applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help hasten our victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read these tales, for within them you will learn how to take greater advantage of the power you infuse into your artifact.\n\nIn stories, we find strength!" }
WordHunterWoW_QuestEN[46145] = { title = "Sterile Surroundings", description = "With the threat of infection dismissed, your allies should be able to press their assault here on the Broken Shore and gain an advantage over the Burning Legion.\n\nLet's leave this place and speak somewhere more... sterile. I hear your order occupies an impressive temple.", objectives = "Return to Netherlight Temple.", completion = "What a charming place this is. Much more hospitable than that demon-infested island." }
WordHunterWoW_QuestEN[46146] = { title = "The Burning Shores", description = "", objectives = "" }
WordHunterWoW_QuestEN[46147] = { title = "Knowledge is Power", description = "Throughout our campaign on the Broken Isles, you have infused your ancient artifact with power. But as the Legion invasion intensifies, it becomes crucial to unlock more of your weapon's potential.\n\nThere is a time for slow, steady progress. But today, we must move with the wind at our backs.\n\nBy devoting our order's resources to studying the weapon's history, I believe we can rapidly enhance the value of the power you apply to the artifact.\n\nShall we begin, <class>t?", objectives = "Provide Order Resources to unlock artifact knowledge.", progress = "I believe applying the resources gathered by our order will allow us to make quick progress.", completion = "Learning more about your artifact weapon will help speed us on the path to victory over the Legion.\n\nIf you supply me with order resources, I can provide research notes on your weapon. Read them, and learn how to take greater advantage of the power you infuse into your artifact.\n\nLet the wind guide your way!" }
WordHunterWoW_QuestEN[46148] = { title = "Furthering Knowledge", description = "We've got the skinny on a bit of the artifact power already and I am working an angle to capitalize on it. \n\nWe've been extorting a group of scribes to put together notes for you, yet they are holding out for a few more resources before they deliver. \n\nThe good news is that we can squeeze them for a few more courses, but after that it will be back to doing our own research.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "Hey, you know what? If you slip me even more order resources, I can put together more notes about your artifact weapon's history and potential.\n\nYou need to power up your weapon, and I can pass along the knowledge to get it done.\n\nBring me those resources as soon as you can. We've got a business to run here!", completion = "These order resources are just the ticket for juicing up your weapon's power.\n\nHere, take these notes. I'm not a big reader myself, but  in this case, it's worth it. That artifact of yours will really get the job done.\n\nGood luck, boss!" }
WordHunterWoW_QuestEN[46149] = { title = "Furthering Knowledge", description = "I am amazed by what we have learned so far. I believe I can prepare for you some notes based on our initial research to get you caught up quickly.\n\nIt will take just a few more resources to prepare the notes properly.\n\nThese steps we take now should provide a boost to our knowledge and we can delve even deeper into the hidden potential of these weapons.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion must fall!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!" }
WordHunterWoW_QuestEN[46150] = { title = "Furthering Knowledge", description = "The amount of power in these artifacts is incredible and we have only scratched the surface. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. \n\nThis is only the first step, with more resources we should be able to help you catch up even more.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with irresistible power.\n\nBring me those resources as soon as you can. Our victory awaits!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the dark secrets within and apply the knowledge you have learned.\n\nAll enemies will fall before us!" }
WordHunterWoW_QuestEN[46151] = { title = "Furthering Knowledge", description = "I am surprised and awed each day I delve deeper into the history of these weapons.  \n\nOur researcher has been going extremely well and we have been busy preparing notes for you. With a few more resources I am sure we can prepare something to boost your artifact knowledge a little. \n\nRemember though, this is only a first step. These weapons have been around longer than most recorded history so much deeper knowledge will take time.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I kin scribe further notes 'bout yer artifact weapon's hist'ry an' potential.\n\nThis knowledge'll be crucial fer infusing yer weapon with additional pow'r.\n\nBring me tha resources as soon as ye can. The Legion must fall!", completion = "The order resources ye 'ave provided be crucial ta further empowerin' yer weapon.\n\nTake these notes. Read tha research an' apply tha knowledge ye 'ave learned.\n\nOnward ta vict'ry!" }
WordHunterWoW_QuestEN[46152] = { title = "Furthering Knowledge", description = "Through pain and blood we have cut through the initial layers of research. \n\nWe have been busy preparing notes for you and with a few more resources we can get you something to boost your artifact knowledge. \n\nThis is only the first step, more resources will be required to catch you up further.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion will cry out in agony as they die!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!" }
WordHunterWoW_QuestEN[46153] = { title = "Furthering Knowledge", description = "The amount of power in these artifacts is incredible and we have only scratched the surface. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. \n\nThis is only the first step, with more resources we should be able to help you catch up even more.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion will fall!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nVictory will be ours!" }
WordHunterWoW_QuestEN[46154] = { title = "Furthering Knowledge", description = "The amount of power in these artifacts is incredible and we have only scratched the surface. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. \n\nThis is only the first step, with more resources we should be able to help you catch up even more.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. Balance must be restored!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!" }
WordHunterWoW_QuestEN[46155] = { title = "Furthering Knowledge", description = "Studying these ancient magic and metals has given us great insight into the potential of these weapons.\n\nJust as these weapons were forged with time and effort so can we forge you instruction on how best to wield and unlock them. With a few more order resources we will have a course completed for you to increase your knowledge.\n\nThis is only breaking the surface of what we will unlock, and as we break through the layers of lost knowledge it will take time to delve deeper.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further legends of your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. For the Valarjarl!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the tales within and apply the knowledge you have learned.\n\nLet the minstrels write songs of your glory!" }
WordHunterWoW_QuestEN[46156] = { title = "Furthering Knowledge", description = "<Sir/Mam>, thank you and the Tirisgarde for this opportunity. Learning about this weapon of yours has been an absolute joy. \n\nTo repay your confidence and trust in my abilities I have organized our researchers notes into an easily digestible course. If you have the resources I know we will continue to output even more valuable insights. \n\nI assure you it has been worth every minute.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. The Legion must fall!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nOnward to victory!" }
WordHunterWoW_QuestEN[46157] = { title = "Furthering Knowledge", description = "The amount of power in these artifacts is astounding and we have only just begun our journey. \n\nOur researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. \n\nThis is only the first step, with more resources we should be able to help you catch up even more.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential. Such intriguing stories to be told!\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as soon as you can. Within words lies wisdom.", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nEvery good story needs a hero!" }
WordHunterWoW_QuestEN[46158] = { title = "Furthering Knowledge", description = "As we follow the stories further back there are strong whispers of even greater potential. \n\nWe have discovered much along the way and we can impart that knowledge. With the help of more order resources we will continue to bring in information from members traveling far and wide.\n\nThese shaman like you are the key to finally unlocking the full potential of these weapons and soon enough we will be back to the time consuming task of chasing down rumors to discover more.", objectives = "Deliver Order Resources to complete a crash course in artifact knowledge.", progress = "With even more order resources, I can scribe further notes about your artifact weapon's history and potential.\n\nThis knowledge will be crucial for infusing your weapon with additional power.\n\nBring me those resources as swiftly as you can. The wind guides us to victory!", completion = "The order resources you have provided are crucial to further empowering your weapon.\n\nHere, take these notes. Read the research and apply the knowledge you have learned.\n\nMay the elements guide us to victory!" }
WordHunterWoW_QuestEN[46159] = { title = "An Urgent Message", description = "We received an urgent message from one of Belath's scouts down on Mardum! I think you had better listen to it.", objectives = "Activate the console to receive the message from Mardum.", progress = "What do you think?", completion = "Lady S'theno went down to lend a hand, but this sounds like it's getting serious!" }
