WordHunterWoW_QuestEN[46176] = { title = "The Archmage Accosted", description = "With the barrier dispelled, Archmage Xylem is finally within reach!\n\nHopefully he'll be cooperative in returning the Iris...", objectives = "Confront Archmage Xylem." }
WordHunterWoW_QuestEN[46177] = { title = "A Portal Away", description = "Xylem may have escaped, but a trace of his portal remains.\n\nNow that you have freed his apprentices from his corruption, I will set them to work trying to find a way to reach him.  Once I find something, I will alert the Kirin Tor.\n\nI only ask that when you do confront the Archmage, that you try to spare his life. I believe that the good man he once was still exists beneath the shadow that has taken him.\n\nFarewell, {name}.", objectives = "Return to Archmage Kalec in Dalaran.", completion = "So Xylem has been corrupted by shadow magic and has escaped with the Focusing Iris? This is not good.\n\nThe Kirin Tor will pool our efforts with those of his apprentici-- I mean, apprentices. We must track down the archmage before he does something drastic.\n\nWe will be in touch." }
WordHunterWoW_QuestEN[46178] = { title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", objectives = "Assassinate the infiltrating homunculi.", progress = "Your blade is not yet bloody enough.", completion = "We have shown the demons why they should truly fear the darkness. Now, Lord Ravenholdt has something for you from his personal collection." }
WordHunterWoW_QuestEN[46179] = { title = "Crushing the Legion", description = "", objectives = "" }
WordHunterWoW_QuestEN[46180] = { title = "Power of Our Enemy", description = "", objectives = "" }
WordHunterWoW_QuestEN[46182] = { title = "Battle for Highmountain", description = "Our defenses have grown in strength, yet the Legion continues to press their assault on Thunder Totem. There is but one way to put an end to this madness - we must strike at the heart of their forces together and bring these attacks to an end.", objectives = "Defeat Fel Commander Erixtol in Highmountain.", completion = "Our efforts today have prevailed over the Legion's presence, though let us not be remiss - our journey has only just begun." }
