WordHunterWoW_QuestEN[46198] = { title = "Gems of Destruction", description = "", objectives = "" }
WordHunterWoW_QuestEN[46199] = { title = "Battle for Azsuna", description = "The vile demon commanding the assault must be stopped. I can get us close, but once we're there I'll rely on you and your allies to help bring down the demonic forces.", objectives = "Defeat Fel Commander Xeritas in Azsuna.", completion = "With the fall of their commander the Legion's presence in Azsuna will be more manageable for our defenders to make headway. For your efforts, we may see the end of these attacks once and for all." }
WordHunterWoW_QuestEN[46200] = { title = "The Matter Resolved... For Now...", description = "You should return to the Kirin Tor. I have no doubt they will want to hear of our success. I will find Lord Erdris, and then I will contact you.", objectives = "Speak with Archmage Modera in Dalaran.", completion = "I am relieved that you have dealt with immediate threat. We barely have enough resources for the Broken Shore as it is!\n\nStill we have something for you..." }
WordHunterWoW_QuestEN[46201] = { title = "By Water Be Purged", description = "", objectives = "" }
WordHunterWoW_QuestEN[46202] = { title = "Rare Elite 14", description = "", objectives = "" }
WordHunterWoW_QuestEN[46205] = { title = "A Conduit No More", description = "One final task remains to sever the Burning Legion's connection to other worlds.\n\nI'll provide you transportation to get you close to the source of power, but you must deliver the final blow to the conduit.", objectives = "Destroy the Legion's Conduit at the Temple of a Thousand Lights.", completion = "With the conduit destroyed, now may be our only chance." }
WordHunterWoW_QuestEN[46206] = { title = "Whispers of a Frightened World", description = "\"Champion! Azeroth needs our help.\"\n\n<Magni Bronzebeard's words echo in your mind, as if rising from somewhere deep and ancient. Azeroth's world soul seeks to deliver a warning to the Speaker, but some force is interfering with the message.>\n\n<Magni has urged you to travel to Sholazar Basin, the vibrant heart of frozen Northrend, to aid him.>", objectives = "Meet Magni in Sholazar Basin and hear the warning.", completion = "This warning is an ill omen indeed, <name>. It seems the fate of Azeroth is tied to that of Argus, the homeworld of the Legion.\n\nWe must uncover the Dark Titan's plan! I believe the Speaker's connection to the world soul will prove crucial to our efforts.\n\nStay vigilant, Archdruid. We must trust in Magni's guidance... and Azeroth's as well." }
WordHunterWoW_QuestEN[46207] = { title = "The Trial of Rage", description = "I wish to extend to you a prestigious invitation.\n\nEvery year I hold a trial for my finest warrior to prove that I command the strongest in this land. I have chosen you to be my champion in this trial.\n\nShould you succeed in completing the trial, I have a prize that will be worthy of your accomplishments awaiting you at the end.\n\nTake what time you need to prepare yourself. Come back and speak with me when you're ready to begin.", objectives = "Speak with Odyn to begin the Trial of Rage scenario. Complete the scenario and claim your prize.", progress = "I have no doubt that you will be victorious in this trial. I look forward to watching it.", completion = "That was truly a grand exposition of <class> skill. I was truly impressed at how you handled Asrea. She will be missed.\n\nBut now on to a grander event. The prize which you so rightfully deserve." }
WordHunterWoW_QuestEN[46208] = { title = "A Godly Invitation", description = "Battlelord {name}, Odyn has requested an audience with you back in Skyhold.\n\nPlease meet with him at your earliest convenience.", objectives = "Speak with Odyn at your order hall in Skyhold.", completion = "Battlelord <name>, I have an offer you may be interested in..." }
WordHunterWoW_QuestEN[46209] = { title = "A Flare In The Dark", description = "", objectives = "" }
WordHunterWoW_QuestEN[46212] = { title = "Get Them Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[46213] = { title = "Crystals Not Included", description = "Turalyon is safe, and we can start to fight back.\n\nFirst things first, we must secure what supplies we can from the crash.\n\nEven though we are blessed by the Light, our ships still rely on crystal technology. From powering our defenses to arming our weapons, we will need to collect as much as we can to fight back against the enemy.\n\nVenture out into the crash and retrieve what crystals you can. While you are out there, keep an eye out for Y'mera. She was separated from us, and will need help.", objectives = "Collect 10 Argunite Crystals.", progress = "I hope you brought backup with you.", completion = "You brought crystals with you? Thank the Light, that's just what we need!" }
