WordHunterWoW_QuestEN[46499] = { title = "Spiders, Huh?", description = "I feel like they're still crawling all over me. I squished one egg and all of a sudden I'm covered head to toe in baby spiders.\n\n<Shivers>.\n\nThat treasure is just sitting there now. The next guy better not be arachnaphlipic... arachnaphonetic? Arachniphant? Afraid of spiders!", objectives = "Look for the rumored treasure in the Creeping Grotto.", progress = "I'm always lookin' for more treasure!", completion = "Oh, look here! You went and got that treasure! Hey... You still got a spider on your shoulder.\n\nLets see what fantastic treasure you brought me... This is it? This is worthless! Here you keep it.\n\nTough break, kid. Keep at it." }
WordHunterWoW_QuestEN[46500] = { title = "Tomb of Sargeras: Legend of the Deep", description = "", objectives = "" }
WordHunterWoW_QuestEN[46501] = { title = "Grave Robbin'", description = "I am not a grave robber, but is it technically grave robbing if the treasure is sitting on a field of bones? It's not like it's buried or nothin'. I'm just gonna sit this one out, just in case.", objectives = "Look for the rumored treasure in the Soul Ruins.", progress = "I'm always lookin' for more treasure!", completion = "You found a key in a chest? Nothing else?\n\nI'm guessing the last guy took all the goods, then accidentally locked the key in the chest. So, you just found a key to a chest that you've already looted. Fantastic work... And people say I suck at this job." }
WordHunterWoW_QuestEN[46502] = { title = "Tomb of Sargeras: Hand of the Legion", description = "", objectives = "" }
WordHunterWoW_QuestEN[46503] = { title = "Tomb of Sargeras: A Lesson in Pain", description = "", objectives = "" }
WordHunterWoW_QuestEN[46504] = { title = "Tomb of Sargeras: Crushing Depths", description = "", objectives = "" }
WordHunterWoW_QuestEN[46505] = { title = "Tomb of Sargeras: Lost But Not Forgotten", description = "", objectives = "" }
WordHunterWoW_QuestEN[46506] = { title = "Tomb of Sargeras: Life After Death", description = "", objectives = "" }
WordHunterWoW_QuestEN[46507] = { title = "Tomb of Sargeras: The Dread Stalker", description = "", objectives = "" }
WordHunterWoW_QuestEN[46508] = { title = "Tomb of Sargeras: Azshara's Reach", description = "", objectives = "" }
WordHunterWoW_QuestEN[46509] = { title = "Tomb Raidering", description = "I said to myself over and over, \"Don't go near the citadel. Don't go near the citadel.\" But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!", objectives = "Look for the rumored treasure outside the Tomb of Sargeras.", progress = "I'm always lookin' for more treasure!", completion = "Did you bother to read the label on this potion? I'm going to assume, no. You may find some sucker who will pay you for it.\n\nBetter luck next time kid." }
WordHunterWoW_QuestEN[46510] = { title = "Ship Graveyard", description = "I haven't told you that I was part of the original landing party when we lost almost everything.  I don't care what treasure is left there, I'll never go back to that beach. Never.", objectives = "Look for the rumored treasure deep in the Forlorn Depths.", progress = "I'm always lookin' for more treasure!", completion = "It's... Wet. This thing is most likely worthless now.\n\nIs there a good piece of treasure on this cursed island? I may not be the brightest tool in the bag, but I'm starting to think this place doesn't really fit my \"chance of death versus treasure\" ratio." }
WordHunterWoW_QuestEN[46511] = { title = "We're Treasure Hunters", description = "I have a feeling you're just using me for tips on where all the best treasure is. From now on I'm naga tell you anything. Did I say, \"naga\" just then? I meant to say, I'm not gonna to tell you naga. I mean nada! Darn it!\n\nOkay. Seems you got me on this one. I'll tell you what, fetch me whatever is in that chest near those naga freaks and I'll make it worth your while.", objectives = "Look for the rumored treasure on the Felrage Strand.", progress = "You fetch that treasure yet?", completion = "This is it? You sure you didn't find anything else? Like a giant pile of gold on top of a statue made of diamonds which was holding a scroll listing the combination to the vault in Ironforge? That would have been pretty sweet.\n\nOh well. I can make this into a paper weight or throw it at a squirrel.\n\nCome back tomorrow, I'll have another job for you." }
